local config = {
  str_story_banner_1 = "¿¡Quién eres!? ¡Sal de mi cabeza!",
  str_story_banner_723 = "Parece que has logrado establecer una conexión con ese aurorian, PlayerName.\n¿Cómo se siente? ¿Estás bien?",
  str_story_banner_2 = "Tratemos de no asustarla y traerla para que pueda hacerse una idea de lo que la rodea...",
  str_story_banner_162 = "¡Usa tus habilidades de Celestita y enséñale el <color=#FFB400>Arreglo de Luces</color>!",
  str_story_banner_3 = [[
Puedes ver <color=#FFB400>casillas de 4 colores diferentes</color>.
Representan los <color=#FFB400>4 elementos</color> de luz esparcidos por el campo de batalla.]],
  str_story_banner_4 = "¡Cuando estén en batalla, los Aurorians resonarán con la energía correspondiente, lo que les permitirá hacer un mejor uso de sus poderes!",
  str_story_banner_5 = "¡Espera espera! ¿Veo estelas de luz? ¿¡Cómo lo hiciste!?",
  str_story_banner_724 = "Buen trabajo, PlayerName. Ahora tú y ese aurorian deberían poder ver estelas de luz de diferentes colores, ¿verdad?",
  str_story_banner_6 = "Al <color=#FFB400>conectando casillas del mismo color para formar un camino de batalla</color>, indicarle que se mueva a lo largo del camino ¡y elimina los Eclipsites!",
  str_story_banner_725 = "No estés nervioso. ¡Tómalo con calma y enséñale el camino de la batalla!",
  str_story_banner_7 = "¿Eso es todo? ¿Todo se resuelve así? Todos los caminos de batalla son los más óptimos, qué es esto ...",
  str_story_banner_12 = "El informante de Eclipse tiene la info. crítica, ¡y debemos recuperarla!",
  str_story_banner_13 = "<color=#FFB400>¡Derrota al informante </color>, luego <color=#FFB400>recolecta inteligencia que cae al suelo </color>! ¡Da la orden, por favor!",
  str_story_banner_21 = "Impresionante... Reconozco tu habilidad para desafiar tu destino.",
  str_story_banner_22 = "Pero ante la voluntad del Eclipse, todos se arrodillarán.\nTu luz eventualmente se apagará.",
  str_story_banner_23 = "¡Hemos recopilado información completa! ¡La referencia repetida a un lugar llamado <color=#FFB400>Cementerio</color> debe ser el <color=#FFB400>Cementerio familiar</color>!",
  str_story_banner_24 = "¿Conoces a Eclipsiano?",
  str_story_banner_27 = "Navegador, el Arrecife tiene la capacidad de <color=#FFB400>¡invocar Runas en ubicaciones aleatorias</color>!\nSi no se destruyen a tiempo, <color=#FFB400>¡estas Runas seguirán convocando a Eclipsites más duros</color>!",
  str_story_banner_28 = "Navegador, el Arrecife tiene la capacidad de <color=#FFB400>¡invocar Runas en ubicaciones aleatorias</color>!\nSi no se destruyen a tiempo, <color=#FFB400>¡estas Runas seguirán convocando a Eclipsites más duros</color>!",
  str_story_banner_29 = "¡Los eclipsites están muy cerca de nosotros! ¡Debemos ganar distancia! Rooney, ¿has <color=#FFB400>acumulado suficiente energía</color>?",
  str_story_banner_30 = "¡Claro! ¡Ya agoté mi energía acumulada! ¡Estoy listo para lanzar mi definitiva en cualquier momento!",
  str_story_banner_31 = "¡Navegador, ordena a Rooney que <color=#FFB400>lance el Definitivo</color>!",
  str_story_banner_32 = "¿Por qué hay tantos? ¿Alguna forma rápida de derrotarlos?",
  str_story_banner_33 = "Navegador, ¡no olvides que también tengo un Definitivo! ¡No te preocupes, déjamelo a mí!",
  str_story_banner_35 = "¿¡Sinsa!? ¿¡Cómo encontraste este lugar antes que nosotros!? ¿No deberías en?...",
  str_story_banner_36 = "Jajaja, es una larga historia...",
  str_story_banner_37 = "<color=#FFB400>¡¡¡Alto!!!</color>",
  str_story_banner_38 = "Navegador, el enemigo esta vez tiene <color=#FFB400>Escudos </color>de varias capas, ¡y cada capa es capaz de <color=#FFB400>resistir el daño una vez</color>!",
  str_story_banner_39 = "Este tipo de escudo <color=#FFB400>se repondrá una vez cada dos rondas</color>, por favor, formula una estrategia  ¡y aprovecha la oportunidad crítica de atacar al enemigo!",
  str_story_banner_40 = "¡Esto es... <color=#FFB400> ANUNCIOS </color>!\n¡Ellos<color=#FFB400>dispararán llamas</color>periódicamente y <color=#FFB400>infligirán un gran daño</color>! ¡Ten cuidado!",
  str_story_banner_41 = "Pero este tipo de daño no distingue entre amigos o enemigos, así que ¿tal vez se pueda explotar?\nDe todos modos, ¡sé flexible, navegador!",
  str_story_banner_42 = "¡Rayos, es el <color=#FFB400>Zapador Eclipse</color>!\nEse tipo tiene la capacidad de <color=#FFB400>aturdir a los enemigos cercanos</color>. ¡Son malas noticias!",
  str_story_banner_43 = "Pero solo puede <color=#FFB400>usar esta habilidad una vez cada dos rondas</color>, ¡ten cuidado con el tiempo y apártate cuando llegue!",
  str_story_banner_44 = "¡Shelt! Como ya dejamos todas las pretensiones, ¡deja de esconderte! ¡No tienes posibilidad de ganar aquí!",
  str_story_banner_45 = "Hmm... no creo que tengan ni idea de lo que pasa ... ¡¡Tú eres el que está a punto de perder, Vice!!",
  str_story_banner_101 = "¡Eres muy bueno liberando el potencial de combate de los aurorians! ¿Es este el poder de un celestita?\nTendré que pensar en un nombre más genial para ti, como ...",
  str_story_banner_701 = "Por favor, deja que Vice se concentre primero en la batalla y deja este pensamiento para después de la batalla ...",
  str_story_banner_102 = "Hay una gran área de casillas azules frente a nosotros, pero aún está lejos de nuestros aurorians en el campo.",
  str_story_banner_103 = "¡Podemos usar la <color=#FFB400>Hab. activa</color> de Dove para cambiar el punto de partida del camino antes de lanzar el ataque!",
  str_story_banner_1001 = "La hab. activa de Dove le permite <color=#FFB400>cambiar de ubicación </color>. ¡Úsalo para <color=#FFB400>moverse a otras casillas dentro del alcance de la hab.! </color>",
  str_story_banner_104 = "¿Mmm? ¿Es mi turno?",
  str_story_banner_167 = "¡La Habilidad Activa de Vice es un ataque que cubre todo el campo! Si quieres usarlo, ¡es el momento perfecto!",
  str_story_banner_1002 = "Todas las habilidades activas <color=#FFB400>tienen un tiempo de enfriamiento</color>,\nlo que significa que <color=#FFB400>tendrás que esperar varias rondas antes de volver a usarlas en la batalla </color>.",
  str_story_banner_1003 = "Déjame ayudar... ¡Guíala a lanzar sus hab.! ¡Recuerda a Vice que se prepare!",
  str_story_banner_1004 = "Entendido, dime cuándo usar mis habilidades—",
  str_story_banner_105 = "¿Este es el diseño del campo de batalla? ¡Espera, tengo una idea!",
  str_story_banner_106 = "El Combo en cadena de la Srta. Blanc puede golpear a los monstruos en un área en forma de diamante, ¿cierto?\n¿Contamos con ella para volver a hacerlo?",
  str_story_banner_187 = "Vice aprende rápido. Parece que ha estado pendiente de sus instrucciones anteriores.",
  str_story_banner_107 = "Ten cuidado; esos eclipsites pueden atacarnos desde la distancia.",
  str_story_banner_108 = "Primero tenemos que matar a estos eclipsites. <color=#FFB400> La habilidad activa </color> de Srta. Blanc puede cambiar el color de las casillas en el campo de batalla, ¡aprovéchalo y pruébalo!",
  str_story_banner_109 = "El poder me hace moverme mucho mejor.",
  str_story_banner_726 = "Bien hecho, PlayerName. ¡Tú y ella parecen trabajar bastante bien juntos!",
  str_story_banner_110 = "Si puedes guiar un camino más largo, ¡los aurorians pueden lanzar un <color=#FFB400>Combo en Cadena</color>poderoso!",
  str_story_banner_111 = "El Combo en Cadena de Vice puede atacar a varios enemigos desde lejos.\n<color=#FFB400>Cuanto más largo sea el camino de batalla</color>, <color=#FFB400>más objetivos de ataque habrá</color>.",
  str_story_banner_163 = "¡Usa un camino más largo para guiarla a usar sus habilidades!",
  str_story_banner_112 = "¡Comenzaremos el esfuerzo grupal a continuación, PlayerName!",
  str_story_banner_164 = "Primero entendamos los elementos y habilidades del nuevo aurorian a través de la telepatía.",
  str_story_banner_113 = "Conecta <color=#FFB400>las casillas amarillos en un camino </color> y, Angel, un <color=#FFB400>Trueno </color> Aurorian, ¡atacará junto con Vice!",
  str_story_banner_114 = "<color=#FFB400>La casilla verde representa el elemento Bosque </color>, y parece que el aurorian está ansioso por ir.",
  str_story_banner_115 = "En tu primera batalla, lo hiciste bastante bien. ¡Pruébalo tú mismo!",
  str_story_banner_169 = "Así es, este es el lugar perfecto para lanzar un ataque.\n¡Finalmente, volé de la manera correcta!",
  str_story_banner_116 = "Las hab. activas de un aurorian pueden cambiar el rumbo de una batalla rápido, sin mencionar que cada hab. tiene efectos diferentes.",
  str_story_banner_117 = "¡Todas las rondas en el objetivo! ¡Eso se sintió muy bien!",
  str_story_banner_1005 = "Esta hab. necesita tiempo de preparación antes de que se pueda utilizar.\n¡Determina un buen momento para usarlo, Navegador!",
  str_story_banner_168 = "¡Exacto! ¡Usar o reservar hab. específicas en dif. situaciones es parte de nuestra estrategia!",
  str_story_banner_118 = "¡Cuidado con las trampas, PlayerName!\nAtacan indiscriminadamente.",
  str_story_banner_190 = "Al formular el camino de la batalla, ten en cuenta este tipo de trampas.",
  str_story_banner_119 = "Las eclipsites también vienen en diferentes formas. La próxima vez, no importa qué tipo de monstruos veas, mantén la calma, navegador.",
  str_story_banner_120 = "<color=#FFB400>¡Es una matriz que invoca constantemente Eclipsites</color>! Lo había visto en manuales de batalla antes, pero nunca pensé que me encontraría con uno aquí ...",
  str_story_banner_121 = "¡Ataca la Misa cada vez que puedas y no te dejes empantanar por los Eclipsites que invoca!",
  str_story_banner_191 = "¡Así es! Si no se elimina a tiempo, ¡los eclipsites recién nacidos siguen apareciendo cada vez más!",
  str_story_banner_122 = "El campo de batalla es un poco estrecho esta vez ... ¡Cuidado, navegador!",
  str_story_banner_123 = "Usa las habilidades de <color=#FFB400> Zoya </color> para ayudar a recuperar PS, ¡y completa esta batalla de manera brillante!",
  str_story_banner_124 = "Este lugar... ¡¿Qué pasó?!",
  str_story_banner_125 = "¡Todos, tengan cuidado! ¿Ves el <color=#FFB400> Abyss </color>, PlayerName?",
  str_story_banner_128 = "Parece que ese monstruo no recibió mucho daño... Mis habilidades son mejores para luchar contra enemigos más peq. Si esto sigue así...",
  str_story_banner_129 = "Al ver el dilema en el que te encuentras ahora, ¿por qué no me dejas cuidar de ti por un tiempo?",
  str_story_banner_130 = "¡Llévame al borde de la grieta y mírame hacer el resto!",
  str_story_banner_131 = "¡Es <color=#FFB400>Dayna</color>! PlayerName, ¡guía un camino de ataque para nosotros!",
  str_story_banner_132 = "¡Funcionó! ¡El daño de ataque de Dayna se extendió por toda la grieta!\nSi podemos repetir eso unas cuantas veces más...",
  str_story_banner_133 = "PlayerName, ¿ves el <color=#FFB400>punto de escape</color> de allí? ¡De ahí saldremos!",
  str_story_banner_134 = "¡El punto de escape permanecerá <color=#FFB400>bloqueado</color>hasta que<color=#FFB400>todos los enemigos sean derrotados</color>!\n¡Hazlo rápido!",
  str_story_banner_135 = "¡El punto de escape está <color=#FFB400>desbloqueado</color>! PlayerName, ¡saca a todos mientras puedas!",
  str_story_banner_136 = "¡Si alcancemos el punto de escape, estaremos a salvo!",
  str_story_banner_137 = "¿Recuerdas? Los aurorians tienen diferentes habilidades y cualquiera puede cambiar el rumbo de la batalla.",
  str_story_banner_186 = "¡Especialmente cuando estas hab. se usan en <color=#FFB400>combinación</color>!",
  str_story_banner_138 = "Cuantas más casillas azules haya alrededor de <color=#FFB400>Vice</color>, más fuertes serán los efectos de sus habilidades.\nAdemás, <color=#FFB400>Srta. Blanc</color> puede convertir los casillas circundantes en azules...",
  str_story_banner_139 = "¿Entiendes lo que digo? Usemos <color=#FFB400>¡La habilidad de conversión de casillas de Srta. Blanc primero</color>!",
  str_story_banner_140 = "¡Ahora, <color=#FFB400>activa la habilidad activa de Vice</color> y maximiza el daño!",
  str_story_banner_141 = "Tenemos oportunidades adicionales para actualizar nuestras habilidades. ¡Depende de ti formar una estrategia de acuerdo con la situación en el campo de batalla!",
  str_story_banner_142 = "Se siente como si alguien estuviera mostrando el camino.\nEl momento del ataque y la elección de la ruta es inteligente...",
  str_story_banner_143 = [[
Bueno, si debo ir...
No creo que pueda ser de mucha ayuda...]],
  str_story_banner_144 = "Déjamelo a mí. ¡Liderar el camino es también mi especialidad!",
  str_story_banner_145 = "Sin miedo. ¡Piensa racionalmente antes de tomar una decisión!",
  str_story_banner_146 = "¿Tienes un mom. difícil? Recuerda, ¡el camino de batalla más largo no siempre es la elección correcta!",
  str_story_banner_188 = "Ahora mismo necesitas el poder de <color=#FFB400>Zoya</color> para conectar la ruta <color=#FFB400>azul</color>\n¡y usa su <color=#FFB400>habilidad curativa</color>!",
  str_story_banner_147 = "¡En la batalla, es importante tener compañeros con habilidades curativas!",
  str_story_banner_148 = "<color=#FFB400>¿Los enemigos están fuera de nuestro rango de ataque</color>esta vez? Tenemos que encontrar una manera de acercarnos ...",
  str_story_banner_149 = "Algunos aurorians <color=#FFB400>pueden convertir las casillas circundantes en un elemento específico</color>, creando un camino de batalla ideal.",
  str_story_banner_183 = "<color=#FFB400>Srta. Blanc</color> tiene esta habilidad, ¿cierto?",
  str_story_banner_150 = "¡Intentémoslo y lo entenderás!",
  str_story_banner_184 = "¡Lo siento! No estoy acostumbrado a pelear con celestitas\n¡Pero sería genial si pudiera ayudar!",
  str_story_banner_151 = "Illumina agradece tu generosa ayuda, señora de Lumopolis.",
  str_story_banner_185 = "<color=#FFB400>Illumina</color>, <color=#FFB400>Lumopolis</color> ...\nDespués de tantos años, los aurorians todavía se aferran a sus hogares.",
  str_story_banner_152 = "<color=#FFB400>Nemesis</color> y Blanc tienen hab. similares, Némesis puede <color=#FFB400>infligir daño</color>\n¡mientras se vuelven <color=#FFB400>amarillas</color>las casillas circundantes!",
  str_story_banner_153 = "¡El uso flexible de las habilidades de conversión de casillas de los aurorians puede llevar a una exp. de batalla más efectiva!\n¡Recuerda aprender y hacer buen uso de esta estrategia, Navegador!",
  str_story_banner_165 = "Bueno. Para priorizar la eficiencia, ¡dibuja un camino que permita a varios aurorians luchar juntos!",
  str_story_banner_154 = "Los aurorians solo pueden atacar cuando viajan por <color=#FFB400>caminos correspondientes a sus elementos</color>,\npero los capitanes no están restringidos por esto.",
  str_story_banner_250 = "<color=#FFB400>Aurorians de fuego atacan a las casillas rojos</color>, <color=#FFB400>Aurorians de agua atacan a las casillas azules</color>, <color=#FFB400>Aurorians del bosque atacan las casillas verdes</color>, mientras que <color=#FFB400>Aurorians de Trueno atacan a las casillas amarillas</color>.",
  str_story_banner_251 = "<color=#FFB400>¡Elige los colores de conexión que sean razonables para que los aurorians ataquen</color>!",
  str_story_banner_155 = "Navegador, bienvenido al campo Desafío. Solo puedes usar <color=#FFB400>Dayna</color>para completar este desafío.",
  str_story_banner_156 = "Solo tienes <color=#FFB400>5 rondas de batalla</color>. Una vez que te quedes sin rondas, fallarás el desafío. ¡Debes hacer uso completo de la habilidad de<color=#FFB400>daño de área</color> de Dayna!",
  str_story_banner_157 = "La <color=#FFB400>Habilidad activa</color>de Dayna también puede infligir daño de área, ¡úsala a tu favor!",
  str_story_banner_158 = "Ok, navegador, ten cuidado con estos Monstruos de cría. Los eclipsites que convocan\npuede tener un gran impacto en ti.",
  str_story_banner_159 = "¡Ten cuidado, PlayerName! ¡Los Eclipsites esta vez son un poco diferentes!",
  str_story_banner_160 = "¡Vivo, PlayerName! ¡Este tiene un rango de ataque muy amplio!",
  str_story_banner_161 = "¡No descuides los detalles al dar órdenes!\nLa supervivencia del equipo está en tus manos.",
  str_story_banner_170 = "¡Estos Eclipsites son algo anormales! ¡Observémoslos de cerca!",
  str_story_banner_171 = "Son los exploradores del enemigo. ¿¡Tratan de reunir <color=#FFB400>info.</color>sobre nosotros en el caos!? ¡Debemos recuperarlo todo!",
  str_story_banner_172 = "Intenta identificar los Eclipsites de esta forma, ¡la <color=#FFB400>intel</color>está en ellos!",
  str_story_banner_173 = "Una vez se recupere suficiente información, <color=#FFB400>retiraremos</color> lo antes posible.\n¡La Subciudad no puede aguantar mucho más!",
  str_story_banner_174 = "¡Presta atención al pequeño Eclipsite volador a lo lejos!\nEl manual de batalla los señala específicamente como \"Peligrosos.\"",
  str_story_banner_175 = "¡Las Eclipsites de este tipo se mueven muy rápido y deben tratarse con cuidado!",
  str_story_banner_727 = "¡Oooh! Así que este es un sendero de luz.\n¡Aquí es donde tenemos nuestras batallas!",
  str_story_banner_728 = "¡Guau! ¡Estás a la altura de tu reputación celestita!\n¿Qué tal si me muestras tus habilidades de mando?",
  str_story_banner_176 = "¿Ves esa cosa brillante en el campo, chico? ¡Es un <color=#FFB400>cristal de meteorito</color>!",
  str_story_banner_177 = "Puede liberar energía de luz condensada <color=#FFB400>para atacar automáticamente al enemigo con más PS</color>. ¡Solo tienes que caminar hasta él! ¡Ni siquiera necesito contarte el resto!",
  str_story_banner_178 = "Todavía quedan dos Cristales. Veamos si podemos eliminar la <color=#FFB400>Eclipsite Grande</color> en la distancia.\n¡Muévete, muévete!",
  str_story_banner_179 = "¡Maldita sea! ¡Es un gran enemigo! ¡Navegador, da un paso atrás! ¿Dónde está mi manual?\nDéjame encontrar la descripción:",
  str_story_banner_180 = "¡Es una <color=#FFB400>instalación de defensa defectuosa</color>! Las cosas se están volviendo más caóticas, ¡asegúrate de mantenerte concentrado!",
  str_story_banner_181 = "Podríamos encontrarnos con muchas trampas complejas en el futuro,\n¡Tratemos esto como una especie de tutorial!",
  str_story_banner_192 = "PlayerName, has dominado muchas técnicas de combate, y ahora te voy a contar una nueva ...",
  str_story_banner_193 = "Ya sabes que las habilidades de los aurorians y las longitudes de los caminos están relacionadas. <color=#FFB400>Si el camino alcanza una cierta longitud</color>, los aurorians pueden ingresar <color=#FFB400>Hora de Aurora</color>.",
  str_story_banner_194 = "Hora de Aurora es un antiguo secreto que ni siquiera los propios aurorians tienen claro. Quizás algún día podamos hacer brillar la verdad sobre ese secreto de los cielos...",
  str_story_banner_195 = "¡Ok, ahora creemos una Hora de Aurora!",
  str_story_banner_196 = "Logra Híper conexión para ingresar a Hora de Aurora. ¡Los aurorians <color=#FFB400>tendrán otra oportunidad de actuar</color>!",
  str_story_banner_197 = "Con un uso inteligente, obtendrás los beneficios ...",
  str_story_banner_198 = "N-navegador, ¿es esta Aurora? ¡Es como si el mundo se hubiera detenido! ¡Ahora es la oportunidad para eliminar a estos enemigos!",
  str_story_banner_199 = "Esta es una etapa especial. ¿Podría mejorar ciertas técnicas de combate?",
  str_story_banner_201 = "Ok, ¡utiliza al máx el Combo de Cadenas de Vice para eliminar a los Eclipsites!",
  str_story_banner_202 = "El terreno abisal nos está separando del enemigo. Necesitamos pensar en una contramedida ...",
  str_story_banner_203 = "Lo que dijo Vice es correcto. ¿Ves los casillas azules del campo de batalla? ¡Vámonos!",
  str_story_banner_207 = "¡Procede a la salida rápidamente!",
  str_story_banner_210 = "Eh, este Sendero de Luz parece interesante. Quizás es hora de que domines la próxima clave de la batalla.",
  str_story_banner_211 = "¿Ves el diseño de las <color=#FFB400>casillas rojos</color>?",
  str_story_banner_212 = "Las habilidades de los aurorians están relacionadas con la longitud de los caminos. Si <color=#FFB400>la ruta se conecta para alcanzar una cierta longitud</color>,\nLos aurorians entrarán en <color=#FFB400>Hora de Aurora</color>.",
  str_story_banner_213 = "Hora de Aurora es un antiguo secreto... Quizás, al igual que la Noche Blanca...es un misterio que nos espera resolver.",
  str_story_banner_214 = "¡Ok, ahora creemos una Hora de Aurora!",
  str_story_banner_215 = "La situación se pone complicada... Concéntrate, Celestita.\n¡Veamos qué tienes!",
  str_story_banner_216 = "Ten cuidado con esas armas de batalla especiales. Atacarán <color=#FFB400>el primer objetivo frente a ellos en línea recta </color>, ¡y DUELE!",
  str_story_banner_217 = "Nuestros \"profesionales\" ya están desmantelando a estos tipos, ¡así que solo necesitas <color=#FFB400> resistir 7 rondas más </color> para ganar! Puedes comprobar tu progreso aquí.",
  str_story_banner_218 = "¡Vamos! ¡Muéstrales que no es tan fácil dejarnos inconscientes!",
  str_story_banner_219 = "Navegador... Esto es urgente; debemos proteger a Eve.",
  str_story_banner_220 = "Eve es vulnerable a los ataques enemigos, ¡así que debemos ser más rápidos!",
  str_story_banner_221 = "Navegador, esta vez también contamos contigo. ¡Creo en ti!",
  str_story_banner_222 = "¡Navegador, el <color=#FFB400>Colector</color> está siendo atacado por Eclipsites!\n¡<color=#FFB400>Debemos proteger el dispositivo</color>!",
  str_story_banner_223 = "Ahora que las Eclipsites están en una posición ventajosa, ¡tenemos que eliminar las que se nos escabulleron!",
  str_story_banner_224 = "El Colector tiene algunos atributos sencillos que pueden ayudarnos a luchar contra estes Eclipsites.\nTen en cuenta que los atributos <color=#FFB400>sólo pueden usarse una vez por ronda.</color>",
  str_story_banner_225 = "Los Eclipsites seguirán llegando, ¡debemos resistir!\n¡Debemos <color=#FFB400>proteger al Colector</color> de la destrucción!",
  str_story_banner_226 = "La activación de las funciones del colector cuesta energía. Notaste la <color=#FFB400>Barra de energía</color>, ¿verdad?",
  str_story_banner_227 = "El ataque anterior provocó algunas grietas en el Colector. ¡Hagamos algunas <color=#FFB400>Reparaciones de emergencia</color>!",
  str_story_banner_228 = "¡Aaaargh, esto no tiene fin! ¡Recuerda usar el <color=#FFB400>Escudo de Energía</color> del Colector cuando estés en un apuro! ¡Puede soportar daños <color=#FFB400>3 veces</color>!",
  str_story_banner_229 = "Estos bastardos están realmente locos, tratando de evitar que despeguemos.\nAdemás, el Sendero de Luz tampoco es ideal. Estamos en problemas.",
  str_story_banner_230 = "Oye, oye. En un momento como este, es mejor usar a alguien con capacidad de ataque grupal, ¡cómo yo!",
  str_story_banner_704 = "¡Apareció de nuevo! ¿¡La astuta Sra. Dayna!?",
  str_story_banner_231 = "¡Apareció de nuevo! ¿¡La astuta Sra. Dayna!?\nShhh, cállate. Con el arreglo actual de Lumina... ¡Sí! ¡Rápido! ¡Ponme de <color=#FFB400>Capitán</color>!",
  str_story_banner_232 = "¿Herido? Deberías conseguir que <color=#FFB400>Zoya</color> te trate.",
  str_story_banner_233 = "¡No debes ignorar el excelente camino a su lado también! <color=#FFB400>¡Deja que Zoya esté en la parte superior</color> y luego guíanos por el camino amarillo!",
  str_story_banner_234 = "Ahora es mi turno de lidiar con estos enemigos dispersos. navegador, recuerdas cómo cambiar de capitán, ¿verdad?\nTen en cuenta que <color=#FFB400>solo puedes cambiar el capitán 3 veces por batalla</color>, ¿de acuerdo?",
  str_story_banner_235 = "¡Usa a los capitanes para cambiar el rumbo de una batalla!",
  str_story_banner_236 = "Ugh... Estas molestas piedritas... Qué irritante... ¡simplemente rómpelos en pedazos!",
  str_story_banner_237 = [[
El resplandor de estas Eclipsites...
Nos hemos encontrado con un gran problema, PlayerName.]],
  str_story_banner_238 = "¡\"<color=#FFB400>Resistencia a ataques físicos</color>\" reduce significativamente el <color=#FFB400>daño físico</color>! ¡Parece que solo <color=#FFB400>Combo en Cadena</color> y <color=#FFB400>Habilidad activa</color> causarán un daño notable!",
  str_story_banner_239 = "Este eclipsite tiene una forma llamativa... Si mal no recuerdo, ¡puede lanzar <color=#FFB400>relámpagos potentes</color>!",
  str_story_banner_240 = "<color=#FFB400>Toque el Eclipsite</color> para ver la ubicación exacta del objetivo. ¡Condúcenos a la victoria!",
  str_story_banner_241 = [[
Creo que esta es la primera vez que nos encontramos con este tipo de eclipsite.
Dame un segundo para comprobar el registro. Este es un problema ...]],
  str_story_banner_242 = "¡Lo encontré! Este tipo de Eclipsites <color=#FFB400> puede proporcionar beneficios a los compañeros</color> ¿Deberíamos deshacernos de él primero ...?",
  str_story_banner_243 = "Lo que va, vuelve, ¿eh? ¿Recuerda el Eclipsite con alta resistencia al ataque normal?\nEste es todo lo contrario. ¡Tiene <color=#FFB400>Resistencia a la habilidad</color>!",
  str_story_banner_244 = "¡<color=#FFB400>Combos en cadena</color> y <color=#FFB400>Habilidades activas</color> infligen <color=#FFB400>mucho menos daño</color>! En otras palabras, ¡un golpe a la vez hasta que baje!",
  str_story_banner_245 = "¿Qué? ¿Por qué hay este tipo de eclipsites aquí? ¡Retrocede, Navegador!",
  str_story_banner_246 = "Este se <color=#FFB400>autodestruirá</color> cuando su PS caiga por debajo de cierto valor, ¡causando un daño masivo al área circundante!\n¡Intenta usar ataques a distancia!",
  str_story_banner_247 = "Vamos, por supuesto que surge algo nuevo...",
  str_story_banner_248 = "\"Este tipo de eclipsite se ha mejorado con elementos, y solo los aurorians con <color=#FFB400>contra elementos</color> pueden infligirles daño de forma eficaz...”",
  str_story_banner_713 = "Este es contrarrestado por el elemento Agua, así que déjamelo a mí.\nSi dejas que alguien más ataque, será complicado...",
  str_story_banner_249 = "¡Gracias a tu guía, descubro que mi poder de combate ha mejorado mucho en las últimas batallas!",
  str_story_banner_252 = "¡No dejes ir estos Eclipsites! ¡Sigamos trabajando en tándem!",
  str_story_banner_253 = "Los Sabueso de hechizos tienen 3 capas de escudo. Intentar romper sus escudos de una vez es difícil ...",
  str_story_banner_254 = "¡Hazme capitán ahora!\n¡De esta manera, usar <color=#FFB400>Agua</color> nos permite a Vice y, la Srta. Blanc y a mi atacar juntos!",
  str_story_banner_255 = "PlayerName, ¿te diste cuenta? ¡El daño recibido por estos dos sabuesos es diferente!",
  str_story_banner_256 = "Los eclipsites también tienen elementos.\nAtacar una eclipsite con un elemento adecuado causa un daño mayor.",
  str_story_banner_257 = [[
Agua contrarresta fuego, Fuego contrarresta Bosque, Bosque contrarresta Trueno,
y el trueno contrarresta el agua!]],
  str_story_banner_258 = "PlayerName, ¡guíanos para derrotar a estos eclipsites!",
  str_story_banner_259 = "Si asignas a Vice como el capitán de la siguiente sección de fichas amarillas, ¡ella y yo podemos atacar juntos!",
  str_story_banner_301 = "¡Aah, estos Soldados Lumo realmente me recuerdan los viejos tiempos!",
  str_story_banner_302 = "<color=#FFB400>¡Toca</color> para comprobar su <color=#FFB400>información detallada</color>!",
  str_story_banner_303 = "¡Ho! ¡Echa un vistazo! ¿Qué son éstos? ¿Lumopolis incluso está desplegando estas <color=#FFB400>trampas</color>obsoletas?",
  str_story_banner_304 = "El olor a peligro... siento como si hubiera visto la luz amarilla en esta trampa en algún lugar antes...",
  str_story_banner_305 = "¡Así que es la Ballesta de parálisis! Déjame ver... Debería haber un <color=#FFB400>botón de activación</color>en algún lugar...",
  str_story_banner_306 = "¡Lo encontré! Tee-hee, solo tenemos que abrirnos paso con cuidado... Espera, parece que hay algo mal con la posición de las escorias de Lumopolis... ¿Qué tal?...",
  str_story_banner_307 = "¡Usar los dispositivos de estas escorias para golpearse a sí mismos es estimulante! Siempre que tengamos cuidado y <color=#FFB400>evitemos estar en la línea de fuego de los dispositivos</color>, ¡estará bien!",
  str_story_banner_308 = "¡Espera! ¡Hay algo sospechoso en los enemigos que tenemos ante nosotros! ¿Qué hace Lumopolis de nuevo?",
  str_story_banner_309 = "Brock, ¡he oído hablar de esto antes! ¡Parece que puede generar fantasmas para <color=#FFB400>evadir ataques</color>!",
  str_story_banner_310 = "¡Pero los fantasmas <color=#FFB400>no pueden soportar las trampas paralizantes</color>! ¡Golpeémoslos con las trampas!",
  str_story_banner_311 = "...¡Qué demonios! ¡Estaba justo ahí! ¡Parece que necesitamos usar las trampas!",
  str_story_banner_312 = "¡Sí, Brock! ¡Es difícil lidiar con estos bastardos! <color=#FFB400> ¡Utiliza más estas trampas </color>!",
  str_story_banner_313 = "Podemos dejar que las trampas de parálisis golpeen a esos bastardos, ¿verdad?\n¡Creo que lo tengo!",
  str_story_banner_314 = "¿¡Qué dispositivo es esta vez!?",
  str_story_banner_315 = "¿Es esto... Uh, supongo que es una especie de <color=#FFB400>cinta transportadora</color> ...?\n¿De dónde diablos sacan estos aparatos raros...?",
  str_story_banner_316 = "¡Cuidado! ¡Esta cosa se mueve, así que no te envíen a los enemigos!",
  str_story_banner_317 = "¿Eh...? Este Eclipsite ... ¿es lindo?",
  str_story_banner_318 = "¡No, no te dejes engañar por su apariencia!\nSi es un eclipsite, ¡es nuestro enemigo!",
  str_story_banner_712 = "... Vice tiene razón. Los eclipsites de ese tipo pueden <color=#FFB400>curar a sus compañeros</color>,\nocupémonos de ellos como una prioridad.",
  str_story_banner_319 = "Este gran monstruo parece muy peligroso ...\nPlayerName, ¡ten cuidado!",
  str_story_banner_320 = "¿Qué es esta eclipsite esponjosa?\nCreo que no está en el Manual de batalla...",
  str_story_banner_321 = "¿Intentas engañarme con tu apariencia de nuevo? ¡Navegador, por favor retrocede por ahora!\n¡Déjanos la lucha a nosotros!",
  str_story_banner_322 = "PlayerName, ¿ves el <color=#FFB400>Remolino</color> en el suelo?",
  str_story_banner_323 = "Parece que...<color=#FFB400>¡podemos viajar rápidamente de un lado a otro entre dos Torbellinos</color>! ¡Qué asombroso!",
  str_story_banner_324 = "¿Es una nueva forma de eclipsite? Estoy llegando al final del manual de batalla ...",
  str_story_banner_325 = "PlayerName, pisotea estas <color=#FFB400>fichas de runas</color>, ¡o <color=#FFB400>convocarán a otros Eclipsites!</color>",
  str_story_banner_326 = "¡Es un <color=#FFB400>Siphorb!</color>!\n¡Estos monstruos <color=#FFB400>pueden absorber los mosaicos del mismo elemento para aumentar su daño</color>!",
  str_story_banner_327 = "¡Esta es la <color=#FFB400>Arena Vientre Negro</color> de Umbraton! ¡Solo tenemos que eliminar a los monstruos que escupen oro! ¡Así de simple!",
  str_story_banner_328 = "¿Por qué los PS de estos Eclipsites son tan extraños?\nParecen fuera de lugar...",
  str_story_banner_329 = "Eso es. Cada vez que el PS de un <color=#FFB400>Goldor Oscuro</color> cae por debajo de cierto valor, entrará en el estado <color=#FFB400>Inmunidad al daño</color> en esta ronda. Que terco...",
  str_story_banner_330 = "Goldors Oscuros también pueden realizar <color=#FFB400>ataques</color>de gran alcance. Elige una buena estrategia\n¡y acaba con este enemigo problemático!",
  str_story_banner_331 = "¡Sí! ¡Activamos la <color=#FFB400>Ronda de bonificación</color>! ¡Somos tan afortunados! ¡Navegador, ven rápido!",
  str_story_banner_332 = "<color=#FFB400>Hay un límite de tiempo para la Ronda de bonificación</color>, ¡debemos eliminar estos Eclipsites lo más rápido posible! ¡Haz un buen uso de las habilidades activas de los aurorians!",
  str_story_banner_333 = "¿Notó las <color=#FFB400>balizas</color> en el campo? Pueden <color=#FFB400>proporcionar un escudo que reduce el daño</color> para Eclipsites.\n¡Elabora estrategias en consecuencia!",
  str_story_banner_334 = "En la batalla de la nieve olvidada, cada etapa tiene sus características, ¡recuerda echarle un vistazo!",
  str_story_banner_335 = "Con tantos Eclipsites atraídos, debimos haber desmantelado el Colossus antes de llevárselo ... ¡Oye!",
  str_story_banner_336 = "Aquí hay muchos <color=#FFB400>guijarros</color> que pueden dificultar el movimiento. Mi Combo en cadena puede eliminarlos.",
  str_story_banner_729 = "¡Es tu decisión, PlayerName!",
  str_story_banner_337 = "¡Woah! Hay algunas golosinas mezcladas con estas rocas de vez en cuando. ¡Vamos a echar un vistazo!",
  str_story_banner_338 = "Bueno, esto es bastante doloroso, sin mencionar el hecho de que hay tantos Eclipsites alrededor. ¡Hagamos un buen uso de estas golosinas!",
  str_story_banner_339 = "Este lugar parece un remanente de un <color=#FFB400>antiguo almacén</color>. ¡Tal vez puedas conseguir muchos\nFragmentos de texto aquí!",
  str_story_banner_340 = "¿Ves la <color=#FFB400>trampa</color> en el suelo? Siempre que pasemos por tres fichas trampa, ¡debería abrirse!",
  str_story_banner_341 = "¡Entremos en acción!",
  str_story_banner_342 = "Parece que estamos en el territorio de <color=#FFB400>ladrones de tumbas</color>. ¡Tienen muchas golosinas!",
  str_story_banner_343 = "Si <color=#FFB400>no podemos atraparlos y derribarlos</color>, ¡<color=#FFB400>huirán</color>!",
  str_story_banner_344 = "¡Recuperemos el botín que debería haber sido nuestro!",
  str_story_banner_345 = "Oye, oye. ¿No es él ese Caballero novato <color=#FFB400>Tanchi</color>?\nParece que activó una trampa y ahora está atrapado en ella...",
  str_story_banner_346 = "¡Maldita sea! Se están acumulando eclipsites. ¡No hay tiempo para dudar! <color=#FFB400> ¡Protejamos a este caballero novato </color>!",
  str_story_banner_347 = "¡Cuidado! Esta trampa es muy peligrosa.",
  str_story_banner_348 = "Este tipo de trampa se activa al pisarla. Úsalo con cuidado.",
  str_story_banner_501 = "Navegador, es hora de que te proporcione una comprensión más completa.",
  str_story_banner_502 = "Además del reclutamiento, hay otros sistemas en el Colossus que deben repararse.\n¡Tómate tu tiempo para explorarlos en tus futuras aventuras!",
  str_story_banner_503 = "¡Han aparecido <color=#FFB400>Eclipsites más grandes</color>!\n¡Pero significa que también tenemos <color=#FFB400>más ángulos de ataque</color>!",
  str_story_banner_166 = "¡Fue una gran batalla! ¡He decidido llamarte Navegador!\n¡A partir de ahora serás nuestro líder de equipo!",
  str_story_banner_702 = "Por favor, no pases la pelota con la Capitanía así...",
  str_story_banner_504 = "¿Por qué no despliegas al resto de tus compañeros en la batalla?\n¡Formemos un poderoso escuadrón aurorian-celestita!",
  str_story_banner_505 = "¡Los nuevos miembros están listos!",
  str_story_banner_506 = "Navegador, ¡Las misiones asignadas por el sistema están en su lugar y necesitan tu revisión!",
  str_story_banner_507 = "¿Qué es esta cosa parpadeante, una especie de notificación del sistema Colossus? Vamos a tocarlo y ver.",
  str_story_banner_508 = "Eso es una especie de <color=#FFB400>Recompensa de misión</color>, ¿eh?\n¿Significa que cada vez que se borra una etapa, obtendremos un beneficio como este?",
  str_story_banner_509 = "¡Si no estás seguro de cómo continuar tu aventura, puedes continuar con la guía más reciente a través de la pantalla de misiones!",
  str_story_banner_510 = "¡Ahora sí! ¡Siempre que sea posible, <color=#FFB400>sube de nivel a tus aurorians</color> para mantenerlos en óptimas condiciones!",
  str_story_banner_511 = "¡Estás bastante iluminado! ¡Golpeemos mientras la plancha está caliente! ¡Sígueme!",
  str_story_banner_512 = "Estas misiones te permitirán crecer más rápido. ¡Solo necesitas familiarizarte con el mundo lo antes posible! Primero, ¡echemos un vistazo a lo disponible!",
  str_story_banner_513 = "¿Quién eres? ¿Cómo puedo ayudar?",
  str_story_banner_514 = "Ejem, parece que un compañero potencial quiere unirse.",
  str_story_banner_515 = "La fuerza de Dayna es excelente y ha ganado muchos torneos subterráneos de Umbraton.\npero también es muy esquiva ...",
  str_story_banner_516 = "Bien bien. ¡Sigamos con nuestra aventura!",
  str_story_banner_517 = "¡Es hora de usar Lumamber para <color=#FFB400>reclutar aurorians</color>, Navegador!",
  str_story_banner_518 = "Como dijo Vice, usa el <color=#FFB400>Lumamber</color> para lanzar un destello de señal y, con suerte, algunos aurorians responderán.",
  str_story_banner_182 = "Pero no puedo predecir a donde la luz del destino llevará tu voz\ny quien responderá...",
  str_story_banner_519 = "¡Algunos aurorians respondieron! Estemos listos para coordinar con ellos...",
  str_story_banner_532 = "¡Es hora de mejorar el poder de combate de todos!\nDove, saca tus materiales de mejora...",
  str_story_banner_703 = "¿Quieres volver a requisar mi propiedad?",
  str_story_banner_520 = "¡Ves! ¡Hay recompensas que puedes reclamar de nuevo! Asegúrate de estar atento a estas pequeñas ventajas...",
  str_story_banner_521 = "¡Puedes reclutar 10 aurorians con este valioso regalo!\n¡Nuestro equipo se expande!",
  str_story_banner_522 = "PlayerName, acabamos de recibir noticias del Norte.\n¡Parece que han aparecido nuevas experiencias!",
  str_story_banner_523 = "Parece que hay muchos tipos de experiencias que pueden proporcionar recursos para que los aurorians crezcan.\n¡Míralo cuando tengas tiempo!",
  str_story_banner_524 = "Ah, sí, y se ha activado un nuevo horario. Sería mejor si lo confirmaras lo antes posible.\nToma Vice para echar un vistazo, PlayerName.",
  str_story_banner_260 = "¡Estas misiones <color=#FFB400>se actualizan todos los días</color>! ¡Quizás nos ayuden a abastecernos de algunos de los recursos!",
  str_story_banner_525 = "Consigue recompensas, como Lumambers, acumulando Puntos de Actividad.",
  str_story_banner_705 = "Estos se pueden usar para cubrir los gastos diarios del Colossus en el futuro... También debemos comenzar a aprender a ejecutar el Colossus a partir de ahora...",
  str_story_banner_706 = "¿Parece que ya se ha convertido en su segunda al mando?",
  str_story_banner_526 = "Navegador, ¡cuidado al frente!",
  str_story_banner_527 = "El camino se divide aquí. Uno te llevará hacia adelante en tu aventura, mientras el otro parece <color=#FFB400>ramificarse en otra etapa</color>.\n¡Compruébalo si estás interesado!",
  str_story_banner_528 = "Puedes encontrar algunas batallas especiales en las rutas secundarias. ¡Compruébalo cuando puedas!",
  str_story_banner_529 = "Espera, aunque tocar la Guía de Misión puede llevarte directamente a tu destino,\n¡Encontré otro lugar que nos puede llevar allí! ¡Sígueme!",
  str_story_banner_530 = "En la pantalla de inicio, toca <color=#FFB400>Misiones</color> para ir directamente al destino de tu aventura.\nNo lo sabías, ¿verdad? ¡Me acabo de enterar!",
  str_story_banner_531 = "... Qué niño más terco.",
  str_story_banner_533 = "Una <color=#FFB400>Ascensión aurorian</color> no solo mejora en gran medida las habilidades de la aurorian, sino también aumenta el <color=#FFB400>Nivel Max</color>de la aurorian que es un medio de crecimiento muy importante.",
  str_story_banner_534 = "Puedes ascender a un Aurorian después de recolectar todos los materiales necesarios para la <color=#FFB400>Ascensión del Aurorian</color> y actualizarlo al nivel máximo actual.",
  str_story_banner_535 = "Navegador, acabas de recopilar un material valioso: ¡un <color=#FFB400>Piedra del corazón</color>!\n¡Ahora podemos realizar un <color=#FFB400>Descubrimiento Aurorian</color>! ¡Sígueme!",
  str_story_banner_536 = "¡Llevar a cabo el Descubrimiento Aurorian <color=#FFB400>aumentará los atributos de un Aurorian</color> y mejorará sus <color=#FFB400>habilidades</color>!\n¡Pruébalo!",
  str_story_banner_537 = "¡Todo el Colossus está iluminado! ¿Significa que podemos realizar reparaciones del sistema?",
  str_story_banner_707 = "Igual, ¡demos un vistazo rápido al Colossus! Como santuario, la condición de Soroz también es\n¡muy importante!",
  str_story_banner_708 = "Muchas de las áreas previamente cerradas ahora se pueden desbloquear.\n¡Al fin podemos hacer uso de las habitaciones que permanecieron inactivas durante 17 años!",
  str_story_banner_538 = "Casi lo olvido. ¡Consigamos a la recién contratada <color=#FFB400>Srta. Blanc</color> para unirse a nuestro equipo!",
  str_story_banner_539 = "¡Todos están listos! ¡Sigamos con la aventura!",
  str_story_banner_540 = "La entrada al Territorio Secreto está desbloqueada. Deberíamos explorar un poco.",
  str_story_banner_541 = "La entrada al Territorio Secreto no abre por mucho tiempo, ¡asegúrate de explorar todo lo que puedas mientras esté abierta!",
  str_story_banner_542 = "En el Territorio Secreto, consumiremos MS en lugar de Prisma. ¡Este es un recurso asombroso producido por el Colossus!",
  str_story_banner_543 = "Cada ronda de batalla del Territorio Secreto cuesta 1 MS. Una vez que se gasta toda la EM, ¡no podemos continuar!",
  str_story_banner_544 = "Hay muchos caminos para elegir al luchar en el Territorio Secreto, pero todos conducen al mismo destino. Así que ten cuidado al elegir los caminos, ya que proporcionarán diferentes efectos de batalla ...",
  str_story_banner_545 = "El desafío... para ganar dinero, es necesario para... la reparación y protección de Colossus, así como el costo de nuestra comida... gastos...",
  str_story_banner_546 = "¡Por favor, evita que Vice se emocione repentinamente cada vez que se entera de dinero! ¡Solo descansa y ponte bien!\n¡Has trabajado demasiado!",
  str_story_banner_547 = "Parece haber una variedad de <color=#FFB400>dificultades</color> para elegir, así que solo elige manejar lo que manejas.",
  str_story_banner_548 = "La afinidad entre tú y los aurorians puede influir sutilmente en ellos, por lo que debes preocuparte por ellos.",
  str_story_banner_549 = "¿Tienes algún aurorian en mente? Por ejemplo, tal vez <color=#FFB400>Vice</color>, ¿quién acaba de lastimarse para protegerte? ¿Anímala un poco?",
  str_story_banner_550 = "¿Qué tal elegir un <color=#FFB400>regalo</color> para Vice? Quizás ella se animará de esa manera.",
  str_story_banner_551 = "<color=#FFB400>Regalar</color> puede mejorar tu <color=#FFB400>Afinidad</color> con los aurorians, desbloquear más <color=#FFB400>Archivos</color> e incluso mejorar algunos de sus <color=#FFB400>atributos</color>.",
  str_story_banner_552 = "¡Elije un regalo aquí y luego solo tienes que tocar Obsequio a continuación!",
  str_story_banner_553 = "Estoy tan contento de que Charon esté sano y salvo... ¿Quién sabía que ese tipo tendría ese tipo de\n\"sorpresa\" bajo la manga?",
  str_story_banner_554 = "PlayerName, <color=#FFB400>Cuentos de aventuras</color> ha sido desbloqueado! ¿Te gustaría ver cómo son las aventuras que no son la historia principal?",
  str_story_banner_556 = "Si estás cansado de las aventuras, ¿relájate experimentando estos capítulos adicionales?",
  str_story_banner_557 = "PlayerName, ¿todavía recuerdas la <color=#FFB400>Búsqueda de crecimiento</color>? Creí que habíamos completado bastantes. ¡Echa un vistazo!",
  str_story_banner_558 = "Nada mal, ¿eh? ¡Reclamemos las recompensas!",
  str_story_banner_559 = "Dayna tiene una mirada aguda... ¡Completemos estas misiones rápidamente y\nreclútala para nuestro equipo!",
  str_story_banner_560 = "Acabo de recoger esto de un Eclipsite. Es pesado y parece ser importante... ¿Quizás podría ser útil?",
  str_story_banner_561 = "¡Ese es el <color=#FFB400>Enchufe central</color>! ¡Es un componente importante en la restauración del Colossus y la mejora del Puente!",
  str_story_banner_562 = "Vamos, veamos si esto todavía funciona. ¡Por favor, sigue mi ejemplo!",
  str_story_banner_563 = "Utiliza el <color=#FFB400>Enchufe central</color> para actualizar tu Bridge. ¿Sabes como hacer esto?",
  str_story_banner_564 = "¡No tenemos suficientes materiales para actualizar ahora! ¡Tenemos que hacer clic en <color=#FFB400>Incursión de recursos Colossus</color> para obtener info.!",
  str_story_banner_565 = "PlayerName. Se activó uno de los módulos entre mis antiguos datos no utilizados. ¡Es una coordenada!",
  str_story_banner_567 = "Ahí está...",
  str_story_banner_568 = "El lugar huele mal. Quizás ningún aurorian haya explorado este sitio...",
  str_story_banner_569 = "No estoy seguro del significado de estas coordenadas, pero siento como si estuvieran tirando de mi memoria. ¿Quieres echarle un vistazo?",
  str_story_banner_570 = "El nivel de Lumina en esta área es muy débil. Es como estar en\nel otro lado del continente gobernado por eclipsites.",
  str_story_banner_571 = "Entrar sin protección sería un suicidio. Déjame ver si hay algún artículo que podamos utilizar en el Colossus.",
  str_story_banner_573 = "Esto es inesperado... ¿todavía tengo estas cosas?\n¡Este mini <color=#FFB400>Sol artificial</color> puede protegernos de ser corrompidos por la oscuridad de este Territorio Secreto!",
  str_story_banner_574 = "Por supuesto, el Lumina que proporciona no es ilimitado.\nPuedes ver en el <color=#FFB400>\"MS\"</color> cuánta energía queda.",
  str_story_banner_575 = "A medida que exploras, <color=#FFB400>MS</color> disminuirá gradualmente. Una vez que baja a <color=#FFB400>0</color>, significa que debes escapar. ¡Actúa dentro de tu capacidad!",
  str_story_banner_576 = "Hay un lugar especial en el Colossus para recargar, y si quieres conquistar el Territorio Secreto,\ntendrás que desbloquear ese cuarto.",
  str_story_banner_577 = "¿Qué estás murmurando? El nombre es PlayerName, ¿verdad?",
  str_story_banner_578 = "Si piensas en el Territorio Secreto, te insto a que procedas con precaución.\nAunque las recompensas son excelentes, ya hay suficientes exploradores enterrados allí.",
  str_story_banner_722 = "Tenemos otras cosas más importantes que hacer, así que sal cuando hayas visto lo suficiente. Esperaré afuera.",
  str_story_banner_579 = "PlayerName, ¡hemos recibido un nuevo mensaje! ¡Compruébalo ahora en <color=#FFB400>Buzón</color>!",
  str_story_banner_580 = "PlayerName, se desbloqueó una nueva historia en <color=#FFB400>Capítulos adicionales</color>.\n¿Quieres echarle un vistazo?",
  str_story_banner_581 = "<color=#FFB400>¡Arrastra la palanca hacia abajo</color> y completa el reclutamiento de aurorians!",
  str_story_banner_582 = "PlayerName!\nPodemos usar el <color=#FFB400>Transportistas</color> ¡Tenemos del Coloso aquí!\n¡Reducirán la cantidad de Prisma necesaria para superar etapas y otorgar recursos de inmediato!",
  str_story_banner_583 = "¡Los transportistas son muy valiosos, debes considerar cuidadosamente cuándo usarlos!",
  str_story_banner_584 = "Y, ¡hay un <color=#FFB400>límite de almacenamiento</color> para los transportistas, es mejor usarlos cuando sea necesario!",
  str_story_banner_585 = "¡La exploración ha comenzado!\n¡Recuerda comprobar el perfil del monstruo antes de luchar en el Territorio Secreto!",
  str_story_banner_586 = "¡Este cuarto es diferente, PlayerName!\nLa presencia enemiga parece ser más frecuente...",
  str_story_banner_587 = "Como era de esperar, ¡es un <color=#FFB400>Etapa Elite</color>! Cada etapa de élite tendrá atributos de etapa únicos, ¡debes lidiar con ellos con cuidado!",
  str_story_banner_588 = "Finalmente, llegamos al <color=#FFB400>salón</color>... ¡Podemos <color=#FFB400>recuperar MS</color> aquí y descansar! Debes estar hambriento.",
  str_story_banner_715 = "*Saca una bandeja de órganos de gusanos de arena a la parrilla cuidadosamente preparada*",
  str_story_banner_589 = "La presión aquí es incluso mayor que en las etapas de élite... Ya no tengo mucho que decir, ¿verdad?\nAnte nosotros yace el gran clímax...",
  str_story_banner_590 = "¡Estas son todas las <color=#FFB400>reliquias</color> que hemos recolectado!\nCada reliquia tiene una característica diferente, ¡aunque solo funcionan en el Territorio Secreto!",
  str_story_banner_716 = "Sería bueno si pudiéramos eliminarlos. Tal vez puedan cubrir parte del costo de funcionamiento y mantenimiento del Colossus... Dove ha estado presionando para un aumento salarial...",
  str_story_banner_591 = "Uf... finalmente llegó a su fin...",
  str_story_banner_592 = "Pero lo que dijo Mendelson sobre Schummer y esos tres componentes...\n¿Dónde los vamos a encontrar...?",
  str_story_banner_593 = "Ha surgido una nueva fuente de señal. ¿Quieres investigar la fuente?\nParece ser un nuevo desafío.",
  str_story_banner_594 = "¡Es un terreno de prueba llamado '<color=#FFB400>Cumbre</color>'!",
  str_story_banner_595 = "¡Mejorar un poco tu fuerza antes de embarcarse en tu próxima aventura es siempre una opción!\nPrimero averigüemos más sobre esto, ¿de acuerdo?",
  str_story_banner_596 = "Cumbre... Unas misteriosas ruinas antiguas. Ya que estás aquí, ¿quieres probarlo?",
  str_story_banner_597 = "¡Por supuesto! PlayerName, muchos ya han desafiado la Cumbre, pero nunca tuve la oportunidad de acceder a él. ¡Intentémoslo esta vez!",
  str_story_banner_598 = "Ok, sígueme entonces.",
  str_story_banner_599 = "La Cumbre es un lugar donde se reúnen los <color=#FFB400>cuatro elementos</color>, y hay cuatro de ellos, con un límite de desafío para cada uno. Vayamos a <color=#FFB400>Cumbre escarcha</color> para echar un vistazo.",
  str_story_banner_600 = "PlayerName, debes comenzar desde el <color=#FFB400>primer nivel</color> y llevar a los Aurorians hacia arriba. <color=#FFB400> ¡Solo se permiten Aurorians del mismo elemento correspondiente</color> en cada torre!",
  str_story_banner_601 = "Espero tu actuación. ¡Buena suerte! Los estaré esperando a todos afuera...",
  str_story_banner_602 = "Ya veo. Es un desafío llamado <color=#FFB400>Noche Blanca, Vientre Negro </color>, que ofrece mucho <color=#FFB400> dinero </color> para derrotar enemigos...",
  str_story_banner_603 = "Estas misiones pueden proporcionar ganancias adicionales, así que asegúrate de pasar y completarlas cuando tengas tiempo... Mmmm, ¿qué es esto <color=#FFB400>Noche blanca, vientre negro</color>?",
  str_story_banner_604 = "PlayerName, ¿has notado que en el Territorio Secreto, el PS de cada aurorian es <color=#FFB400>contado individualmente</color>?",
  str_story_banner_605 = "Los miembros de nuestro equipo se dieron cuenta de lo peligrosas que se ponían las cosas...\n¿Dependemos demasiado del Capitán?",
  str_story_banner_606 = "¡Sigue los cambios en el campo de batalla en el Territorio Secreto! Es la primera vez que todos están aquí...",
  str_story_banner_607 = "¡Da la orden! ¡Tenemos plena confianza en ti, PlayerName!",
  str_story_banner_608 = "PlayerName, estos Aurorians han encontrado algunas <color=#FFB400>pequeñas cosas</color> ...\nEs posible que también te interesen, así que ven a verlos.",
  str_story_banner_609 = "Este es un <color=#FFB400>sistema de terminal</color> que permite a los usuarios comunicarse entre sí de forma remota. Te he dado todo el acceso necesario.",
  str_story_banner_610 = "Comparado con un viejo como yo, deberías poder entenderlo más fácilmente.",
  str_story_banner_611 = "Parece que sería mejor discutir algunas cosas cara a cara...",
  str_story_banner_650 = "Recibimos un nuevo artículo. ¡Qué marcas tan fascinantes hay!",
  str_story_banner_651 = "¡El análisis muestra que es en verdad un <color=#FFB400>Cubo de Vacío de Territorio Secreto</color> que revela ubicaciones de Territorios Secretos!",
  str_story_banner_652 = "Ingrese el patrón de superficie en la base de datos de Colossus, ¡tal vez eso desbloquee la Oficina de Exploración! ¡Sígueme!",
  str_story_banner_653 = "Ingresé el mapa en la base de datos y analicé toda la información necesaria para construir la Oficina de Exploración.",
  str_story_banner_654 = "Ahora, comencemos a construir el <color=#FFB400>Oficina de Exploración</color>!",
  str_story_banner_1201 = "¿Qué es esto? Se ve tan extraño... ¿Podría ser algún tipo de trampa?",
  str_story_banner_1202 = "¡Creo que explotaría si golpeara a alguien!\n¿Habrá una forma especial de resolver esto?",
  str_story_banner_1203 = [[
De alguna manera... inesperadamente interesante...
Comparado con solo usar una espada, este estilo de combate  es divertido...]],
  str_story_banner_714 = "¡Pero no debemos bajar la guardia! Si yo puedo usar este método, ¡también el enemigo!",
  str_story_banner_1204 = "PlayerName, no olvides <color=#FFB400>subir de nivel</color> a tus Aurorians. ¡De esta manera puedes ganar la batalla con facilidad!",
  str_story_banner_1205 = "Esta vez, ¡subamos de nivel <color=#FFB400>Srta. Blanc</color>!",
  str_story_banner_1206 = "¿Todavía recuerdas cómo hacerlo? ¡Pruébalo tú mismo!",
  str_story_banner_1207 = "¿Podemos <color=#FFB400>lanzar</color> bombas hidráulicas?\n¿Eso significa que podemos patear Eclipsites en bombas hidráulicas? ¡Probémoslo!",
  str_story_banner_1208 = "Rara vez nos encontramos con esta especie de eclipsites extrañas...",
  str_story_banner_1209 = "¡Cuidado! ¡Estos eclipsites poseen una extraordinaria <color=#FFB400>capacidad de retroceso</color>! Debo anotarlo...",
  str_story_banner_2001 = "Es la primera vez que veo el interior de un Colossus, ¿verdad? Parece bastante desordenado ahora porque la parte más importante, el\n<color=#FFB400>enchufe central</color>, falta.",
  str_story_banner_2002 = "Si es posible, está atento al <color=#FFB400>Enchufe central</color> durante tus aventuras,\nya que puede ayudarme a recuperar mi energía y permitirme utilizar más funciones.",
  str_story_banner_2003 = "Bien, averigüemos primero qué puedes hacer en el Colossus. Las características del Colossus están impulsadas por Lumina,\nasí que familiaricémonos con él.",
  str_story_banner_2004 = "Desbloqueemos la <color=#FFB400>Red Lumina</color>.",
  str_story_banner_709 = "Además, las <color=#FFB400>Luciérnagas</color> son necesarias para desbloquear y mejorar una sala.\nEstos peq. y trabajadores compañeros han estado con nosotros por 17 años.",
  str_story_banner_2005 = "¡Está desbloqueado! ¡Excelente! Puedo proporcionar refugio y proteger a todos.",
  str_story_banner_2006 = "Por favor, echa un vistazo a la <color=#FFB400>Red Lumina</color>.",
  str_story_banner_2007 = "Esta es la <color=#FFB400>Red Lumina</color>. Puedes construir <color=#FFB400>4</color> de ellas, pero tienes que desbloquearlas una por una.",
  str_story_banner_2008 = "Una Rejilla de Lumina no solo <color=#FFB400>proporciona Lumina</color>, sino que <color=#FFB400>también potencia la recuperación de Luciérnagas</color>. Las Luciérnagas se están acercando.",
  str_story_banner_2009 = "Bien, veamos otra información sobre Red Lumina.",
  str_story_banner_2010 = "<color=#FFB400> Los Aurorians se pueden desplegar </color> para trabajar en todas las habitaciones del Colossus para mejorar los efectos de sus características.\n¡Dale!",
  str_story_banner_2011 = [[
Cada Aurorian tiene su propia especialidad, y debemos elegir un Aurorian
que sea adecuado para trabajar en Red Lumina.]],
  str_story_banner_2012 = "Muy bien, vayamos a <color=#FFB400>Pilar de Prisma</color> a continuación. ¡Es un área muy importante!",
  str_story_banner_2013 = "¡Bienvenido de nuevo al <color=#FFB400>Puente</color>! Esta es el área más importante del Colossus, ¡permítanme compartir con ustedes lo que aprendí sobre el Colossus cuando estaba en Illumina!",
  str_story_banner_2014 = "¡El Puente puede aumentar el <color=#FFB400>Ánimo</color> máximo dentro del Colossus! ¡Ve el detalle aquí!",
  str_story_banner_2015 = "Hmm ... Déjame ver, dónde encontrar detalles sobre el Puente...",
  str_story_banner_2016 = "¡Ah, aquí está! Además, si has recopilado un enchufe central, ¡puedes actualizar el puente con él desde aquí!",
  str_story_banner_2017 = "PlayerName, ¡todavía no hay ningún Aurorian desplegado en el Puente! ¿Olvidaste cómo hacerlo?",
  str_story_banner_710 = "¡Permíteme recomendarme! He operado plataformas de control antes,\n¡Y me enseñé a mí mismo cómo operar los sistemas de Soroz! ¡Por favor déjame quedarme en el puente!",
  str_story_banner_711 = "Qué aprendiz más rápido ...\nVice es la mejor persona para el trabajo ahora.",
  str_story_banner_2018 = "Por cierto, me tomé un tiempo para hacer un balance de los recursos restantes y no parece ser suficiente.",
  str_story_banner_2019 = "Quizás deberíamos seguir explorando el interior del Colossus. Quién sabe, ¡tal vez algún lugar que pueda generar recursos\nha vuelto a estar en línea!",
  str_story_banner_2021 = "¿Parece que es una invitación a trabajar junto con otros poderes Aurorians? No sé mucho, pero estos tipos ef. son buenos para recolectar todo tipo de materiales extraños ...",
  str_story_banner_2022 = "Esta es la <color=#FFB400>Cámara luz de las estrellas</color>, ¡una instalación muy importante!",
  str_story_banner_2023 = "La Cámara luz de las estrellas suele producir valiosas <color=#FFB400>Piedras del Corazón</color>, pero a veces <color=#FFB400>gemas estrella</color>raras y<color=#FFB400>SS gemas estrella</color> pueden aparecer como bien. ¡Descúbrelo lentamente cuando tengas tiempo!",
  str_story_banner_2024 = "La recolección de Piedra de Corazón se vuelve más rápida a medida que aumenta el nivel de Cámara luz de las estrellas.\n¡La implem. del Aurorian adecuado puede aumentar la tasa de recolección! ¡Dale una oportunidad!",
  str_story_banner_2025 = "¿Recuerdas el <color=#FFB400>Prisma</color> que usamos en batallas anteriores? Es esencial para ayudar al navegador\nreponer la energía utilizada en las habilidades psíquicas.",
  str_story_banner_2026 = "Pilar Prisma es una instalación muy valiosa que puede convertir Lumina en <color=#FFB400>Prismas</color>.",
  str_story_banner_2027 = "Puedes ver la info de Pilar Prisma en la barra de info rápida en la esquina inferior izquierda.",
  str_story_banner_2028 = "Ve más detalles aquí.",
  str_story_banner_2029 = "¡Esta es la <color=#FFB400>Estación de recursos</color>! ¡Recuerdo todas las cosas importantes al respecto!\n¡Permíteme presentarlo! ¡Ejem!",
  str_story_banner_2030 = "La estación de recursos puede fabricar <color=#FFB400>portaaviones</color>. Ya tienes algunos, ¿verdad?",
  str_story_banner_731 = "Estas son luciérnagas especiales que luchan en tu nombre. <color=#FFB400>Reducirán la cantidad de Prisma necesaria para superar etapas y otorgar recursos inmediatamente.</color>!",
  str_story_banner_2031 = "Repasemos cómo puedes verificar la info de la estación de recursos.",
  str_story_banner_2032 = "El inicio de varias incursiones de recursos depende del nivel de la estación de recursos.\nLos aurorians también se pueden desplegar aquí, ¡así que no lo olvides!",
  str_story_banner_2033 = "Ok, ¡echemos un vistazo a cómo usar Transportadores!",
  str_story_banner_2034 = "PlayerName, ¿recuerdas lo que hablamos, de explorar el Territorio Secreto? ¡La habitación en la que estás ahora se puede usar para transformar \"<color=#FFB400>Soles artificiales</color>\"!",
  str_story_banner_2035 = "Vice parece conocerme de adentro hacia afuera, incluso más que tú, que llevas 17 años conmigo... ¡Asegúrate de mantenerla en el Colossus!",
  str_story_banner_2036 = "Explorar el territorio secreto requiere mucho <color=#FFB400>'MS'</color>, que es un tipo especial de sustancia, y <color=#FFB400>MS</color> representa la cantidad que queda.",
  str_story_banner_732 = "<color=#FFB400>MS</color> se puede recuperar aquí con el tiempo. ¡Ve aquí para más detalles!",
  str_story_banner_2037 = "PlayerName, las coordenadas del Territorio Secreto han sido confirmadas. ¡Vamos allí y echemos un vistazo!",
  str_story_banner_2038 = "¡PlayerName! ¿¡Estás bien!? Lo siento, no pude apuntar a los signos vitales de Nozard en este momento... Pero a esta altura, prob. no sobrevivirá, ¿verdad?",
  str_story_banner_717 = "A continuación, debemos volver a subir a una altitud segura. Aun si estamos fuera de peligro, no debemos relajarnos. No permitamos que más personas sacrifiquen sus vidas.",
  str_story_banner_718 = "Por favor dile que no su culpa. Si hubiera calentado más rápido, estos eclipsites no habrían tenido ninguna posibilidad.",
  str_story_banner_719 = "Hmm... Volar es un poco laborioso... El daño parece ser serio. Permítanme buscar en los alrededores para ver si hay lugares donde podamos recolectar materiales de reparación...",
  str_story_banner_2020 = "PlayerName, la postura de vuelo de Soroz parece sugerir que siente dolor. Supongo que la batalla causo bastante daño...",
  str_story_banner_720 = "¿Mmm? Espera, es una nueva fuente de señal... ¿Qué encontró Soroz?",
  str_story_banner_721 = "Realmente aprecio la preocupación de Vice. Encontré algo: es una especie de prueba que puede darnos <color=#FFB400>materiales de construcción Colossus</color>. ¿Vamos a echar un vistazo?",
  str_story_banner_2039 = "Lamento molestarte, PlayerName. El daño causado por las peleas es particularmente severo...",
  str_story_banner_730 = "Déjame llevarte a algún lado. Si puedes reconstruirlo,\npodrás arreglarme.",
  str_story_banner_2040 = "Este lugar solía estar sin vida. Pero las cosas son diferentes ahora. Puedes restaurarlo a su antigua gloria.",
  str_story_banner_2041 = "El mantenimiento del Colossus y la actualización de los Aurorians requieren muchos recursos, la<color=#FFB400>Estación de recursos</color> existe para descubrir más recursos.",
  str_story_banner_2042 = "Crea una <color=#FFB400>Estación de recursos</color>.",
  str_story_banner_2043 = "Esta sala hará que nuestra colección de recursos sea mucho más efectiva. Aprovéchalo.",
  str_story_banner_2044 = "PlayerName, ¡ahí lo tienes! Encontré una nueva versión de prueba. ¡Quizás podamos conseguir los materiales necesarios para reparar Soroz!",
  str_story_banner_2045 = "¡La fuente de la señal está aquí, PlayerName!",
  str_story_banner_2046 = "Vice te espera aquí. ¡Ve a descubrir lo que necesita!",
  str_story_banner_2047 = "Hmm ... PlayerName, ¿has visto a Vice?",
  str_story_banner_2048 = "El pilar de prisma... Ah, los recuerdo ... ¡Intentemos arreglarlo!",
  str_story_banner_2049 = "Muy bien, el <color=#FFB400>Pilar de Prisma</color> ahora está reactivado. Ven y echa un vistazo, PlayerName.",
  str_story_banner_2050 = "Si tenemos los materiales, ¡también podemos actualizar el pilar de prisma para mejorar su eficiencia de conversión de prisma!",
  str_story_banner_2051 = "Del mismo modo, la implementación de Aurorians específicos también ayuda a mejorar la tasa de conversión del Pilar de Prisma.\n¡Probémoslo!",
  str_story_banner_2052 = "No has olvidado cómo desplegar Aurorians, ¿verdad? ¡Intenta operarlo!",
  str_story_banner_2053 = "El sistema de misiones ha sido actualizado. ¿Deberíamos echarle un vistazo?",
  str_story_banner_2054 = "El enchufe central solo se puede utilizar en el puente. ¡Rápido, ven al puente!",
  str_story_banner_2055 = "Desafía a los jefes de Desolation Codex para recibir un rango, un emblema de avatar y recompensas según el daño que inflijas.",
  str_story_banner_2056 = "Puede ver los requisitos de daño y las recompensas de todos los rangos aquí.",
  str_story_banner_2057 = "Al final de cada ciclo, se emitirán recompensas y emblemas de acuerdo con su rango. Su emblema se mostrará en su avatar personal como símbolo de sus logros.",
  str_story_banner_2058 = "¡Ahora, desafiemos al jefe de este ciclo!",
  str_story_banner_3001 = "La Ascensión Aurorian también desbloqueará equipamiento.\n¡Déjame mostrarte cómo funciona el <color=#FFB400>Equipamiento Aurorian</color>!",
  str_story_banner_3002 = "Cada equipamiento Aurorian es único. Pueden <color=#FFB400>mejorar las habilidades</color>\ny <color=#FFB400>mejorar las habilidades Aurorian</color>.",
  str_story_banner_3003 = "Además, el equipamiento Aurorian puede mejorar el efecto de los <color=#FFB400>contadores elementales</color>, mejorando así las habilidades de los Aurorians.",
  str_story_banner_3004 = "¡PlayerName! El equipamiento Aurorian también se puede actualizar. Por supuesto, cuesta una gran cantidad de materiales especiales. Ven conmigo y compruébalo.",
  str_story_banner_3005 = "¡No tenemos suficientes materiales en este momento!\nPero creo que con PlayerName cerca, ¡los conseguiremos todos!",
  str_story_banner_3011 = "¡Espera! ¿Notaste el <color=#FFB400>icono especial </color> sobre el quinto espacio del equipo?",
  str_story_banner_3012 = "¡El icono significa que puedes agregar <color=#FFB400> Aurorians de apoyo </color> aquí!",
  str_story_banner_3013 = "¡A través de negociaciones, podemos invitar a Aurorians que no estén en el Colossus para ayudar en la batalla! Se llaman Aurorians de apoyo.",
  str_story_banner_3014 = "Debes firmar un pacto con otras organizaciones para llamar a Aurorians de apoyo. ¡Por supuesto, hay algunas organizaciones que están dispuestas a ofrecer ayuda incondicional!",
  str_story_banner_3015 = "No todas las batallas se pueden librar con Aurorians de apoyo, y el mismo Aurorian de apoyo no se puede desplegar más de una vez en un corto período de tiempo.",
  str_story_banner_3016 = "¡Muy bien, PlayerName! Puedes elegir un Aurorian de apoyo que te parezca adecuado. El Aurorian de apoyo ocupará la quinta posición de formación.",
  str_story_banner_3017 = "Por último, recuerda que <color=#FFB400>¡no puedes completar determinadas misiones de clasificación de etapa con Aurorians de apoyo</color>!",
  str_story_banner_3018 = "Desafortunadamente, <color=#FFB400>no puedes completar ciertas misiones de clasificación de etapa con Aurorians de apoyo </color>.",
  str_story_banner_3021 = "¡Acabamos de recibir un mensaje de Illumina, PlayerName!",
  str_story_banner_3022 = "Déjame ver... Mencionó \"<color=#FFB400>Templar Illumina</color>.\" Creo que he oído hablar de ello en alguna parte antes...",
  str_story_banner_3023 = "¿Pueden ser las ruinas recientemente descubiertas?\n¡El lab supuestamente excavó una gran cantidad de materiales que podrían <color=#FFB400>mejorar el equipamiento</color>!",
  str_story_banner_3024 = "¡Descubrámoslo muy rápido!",
  str_story_banner_3031 = "¿Está lista la <color=#FFB400>Oficina de despacho</color>? ¡Esto significa que podremos ayudar a otros rápido!",
  str_story_banner_3032 = "¡Sígueme! ¡Echemos un vistazo a la mesa de arena!",
  str_story_banner_3033 = "¡Podemos ver todas las <color=#FFB400>Misiones de envío </color>Xen la mesa de arena! Mira aquí-",
  str_story_banner_3034 = "La mayoría de las <color=#FFB400>Misiones de envío</color>las realizan las distintas facciones. ¡Completa una misión con Aurorians de la misma facción para obtener recompensas!",
  str_story_banner_3035 = "¡Cada misión requiere tiempo para completarse!\n¡Envía a tus Aurorians una vez que hayas tomado una decisión!",
  str_story_banner_3036 = "¿Por qué no lo pruebas ahora, navegador?",
  str_story_banner_3041 = "¡Oh! Este olor familiar... Es muy débil ahora, ¡pero lo he olido antes en el Illumina!",
  str_story_banner_3042 = "Si no me equivoco, este debe ser un <color=#FFB400>Taller</color> abandonado, ¿verdad?",
  str_story_banner_3043 = "El Taller es un lugar importante donde se pueden elaborar muchos materiales.\nSería un desperdicio no usarlo...",
  str_story_banner_3044 = "¿Ves el <color=#FFB400>horno</color>en el centro? ¡Cuidado, puede hacer calor!\n¡Primero echa un vistazo a la <color=#FFB400>consola</color>!",
  str_story_banner_3045 = "No dejes que los controles te asusten. ¡Es sencillo!",
  str_story_banner_3046 = "Recuerda, cuesta <color=#FFB400>Reactivos atómicos</color> usar el horno. Los reactivos atómicos se producen lentamente aquí.",
  str_story_banner_3047 = "¡Mejora el taller para crear más cosas!\nUn último recordatorio: ¡no juegues con fuego!",
  str_story_banner_3051 = "¡Navegador! ¡Estoy ejecutando un plan que llamo \"Operación Hacer que el Colossus sea como en casa\"!\n¡Ven y <color=#FFB400>decora el Colossus</color> conmigo!",
  str_story_banner_3052 = "...¿No me digas que habrán faldas y corbatas?",
  str_story_banner_3053 = "¡No puedo esperar! ¡Te familiarizaré con lo que necesitas hacer para empezar a decorar!",
  str_story_banner_3054 = "Recogeremos todo tipo de muebles durante nuestras aventuras.\n¡Podemos usarlos para decorar el Colossus!",
  str_story_banner_3055 = "He traído algunas cosas de otro lugar por ahora. ¡Probémoslo primero!",
  str_story_banner_3056 = "Cada mueble es diferente.\nA continuación se ofrecen unas sencillas instrucciones. ¿Por qué no lo intentas?",
  str_story_banner_3057 = "Tienes que colocar los muebles en el lugar correcto. Muévelo medio centímetro hacia ese lado, ¿Ok?",
  str_story_banner_3058 = "¡Estupendo! ¡Se ha colocado el mobiliario! Aún no has terminado.\nNecesitas <color=#FFB400>guardar</color> para conservar los cambios que realizaste.",
  str_story_banner_3059 = "¿Has notado? ¡El mobiliario ha mejorado el <color=#FFB400>Ánimo</color>de la habitación!",
  str_story_banner_3060 = "Aquí es donde puedes ver el <color=#FFB400>Ánimo</color> de Colossus.",
  str_story_banner_3061 = "¡El estado de ánimo parece afectar a todos! Entonces, ¡también es deber del Navegador decorar el Colossus!",
  str_story_banner_3062 = "¡Eso es todo sobre \"Operación Hacer que el Colossus sea tan cálido como en casa\"! ¡Ya estoy deseando ver tus creaciones creativas, Navegador!",
  str_story_banner_3063 = "¡Recibimos algunos pactos nuevos! ¡Ahora podemos invitar a los Aurorians que no se han unido a nosotros en el Colossus para brindar apoyo temp. en la batalla!",
  str_story_banner_3071 = "¡PlayerName! ¡Ven conmigo y te mostraré algo interesante!",
  str_story_banner_3082 = "¡Aparentemente, puedes reclutarlos a todos completando una serie de <color=#FFB400>misiones especiales</color>!",
  str_story_banner_3083 = "¡Echemos un vistazo a sus archivos y <color=#FFB400>elije qué Aurorian reclutaremos primero</color>!",
  str_story_banner_3084 = "Ahora, veamos... ¿Qué debemos hacer para completar este reclutamiento?",
  str_story_banner_3086 = "Después de completar todas las misiones de la fase, la siguiente fase se desbloqueará automáticamente. Si puedes completar todas las misiones, obtendrás este Aurorian.",
  str_story_banner_3087 = "Ten en cuenta que solo contarán las <color=#FFB400>misiones</color>para el<color=#FFB400>Aurorian actualmente reclutado</color> ¡y no se logrará ningún progreso para los Aurorians que no estén siendo reclutados!",
  str_story_banner_3091 = "Parece que este desafío de reclutamiento siempre estará disponible. ¡Asegúrate de comprobar el progreso de tu misión de vez en cuando!",
  str_story_banner_3092 = "Una fuerza misteriosa y poderosa nos espera más adelante... ¿Deberíamos ir a explorarla?",
  str_story_banner_4000 = "¿Cuándo terminará todo esto?",
  str_story_banner_4001 = "No importa cuánto tiempo tengas, nunca podrás acabar con esas cosas llamadas Eclipsites.",
  str_story_banner_4002 = "Esto me recuerda la mentira. Si vuelvo a verlo, lo asaré al fuego sin pensarlo.",
  str_story_banner_4003 = "Siempre hay alguien que cree que nos convertiremos en Eclipsites, pero las mentes de esas personas son más aterradoras que las Eclipsites.",
  str_story_banner_4004 = "Ese traidor lo está haciendo bien. Ojalá hubiera muerto.",
  str_story_banner_4005 = "Puede que sea solo yo, pero siento que el traidor sigue vivo.",
  str_story_banner_4006 = "Lástima que mi rabia no se manifestó, o lo habrían incinerado antes de que mi espada lo golpeara.",
  str_story_banner_4007 = "Prob Claymore decidió que era más probable que me resistiera, así que primero me hackeó.",
  str_story_banner_4008 = "¿Es este el comienzo de una nueva historia? Con suerte, un mejor final esta vez.",
  str_story_banner_4009 = "Pensé que sería mejor que los Cazadores fueran solos, pero Frostfire y Regal siempre causan problemas cuando lo hacen.",
  str_story_banner_4010 = "Aquellos que tienden a perder el control necesitarán a alguien racional para volver al camino correcto.",
  str_story_banner_4011 = "Tal vez otros no puedan entender por qué Claymore hizo esa llamada, pero no, no planeo explicárselo. Simplemente lo acepté y lo grabé.",
  str_story_banner_4012 = "En las historias, aquellos que superan las pruebas y tribulaciones serían felices.",
  str_story_banner_4013 = "Quizás no logramos superar las pruebas que se nos plantearon.",
  str_story_banner_4014 = "Justo a tiempo. No importa cuándo siempre tenga la energía para matarlos.",
  str_story_banner_4015 = "Si no puedes soportarlo, gira hacia el otro lado y no mires. No quiero que me regañes por cómo mato a los Eclipsites como los demás.",
  str_story_banner_4016 = "Fui elegido, entrenado y luego acepté los poderes voluntariamente para erradicarlos a todos, ¿por qué los Aurorians intentarían detenerme?",
  str_story_banner_4017 = "Siento que recuerdo algo que preferiría no... No, todavía no puedo.",
  str_story_banner_4018 = "¿Por qué estaba hinchado de odio en ese momento?",
  str_story_banner_4019 = "No quieren que se mencionen más sus nombres anteriores. Aunque no entiendo por qué.",
  str_story_banner_4020 = "No importa, no voy a reflexionar sobre algo tan profundo. Todo lo que quiero hacer es cazar Eclipsites como antes.",
  str_story_banner_4021 = "¡Pero no seas como mi viejo capitán, desenvainando una espada y apuñalándome por la espalda de repente! ¡Eso no está bien!",
  str_story_banner_4022 = "¿Qué? ¿Ha pasado mucho tiempo desde? ¿Y el mundo no es el mismo?",
  str_story_banner_4023 = "Solo no entiendo.",
  str_story_banner_4042 = "¡Navegador! Hemos encontrado algunas cosas interesantes mientras reparamos el Colossus.",
  str_story_banner_4043 = "Necesitaremos algunos materiales para reparar esta habitación.",
  str_story_banner_4044 = "Este es un sistema de comando simulado que puede ayudarte con tu entrenamiento. Puede crear varias situaciones de batalla de acuerdo con sus especificaciones.",
  str_story_banner_4045 = "Obtienes Puntos de Mando por completar escenarios de combate. Algunas batallas también te darán fragmentos de datos.",
  str_story_banner_4046 = "¡Puedes elegir un disco de datos y comenzar ahora mismo!",
  str_story_banner_4047 = "La sala de simulación está terminada... ¡Averigüemos cómo usarla!",
  str_story_banner_4050 = "¡El fin! Maiden and the Ruins ha comenzado! Veamos qué hay de nuevo en este evento.",
  str_story_banner_5001 = "¡Bienvenido a una nueva aventura! ¡Desbloquea nuevas historias y premios en este evento de <color=#FFB400>Cloud Blossom Destiny</color>!",
  str_story_banner_5002 = "Gasta prismas en los desafíos de la historia principal y en las incursiones de recursos para conseguir <color=#FFB400>Pétalos de Flor de Nube</color> para el evento. Desbloquea escenarios y recompensas del evento con Pétalos de Flor de Nube.",
  str_story_banner_5003 = "¡Nuevas historias por descubrir! ¡Desbloquéalas con los Pétalos de Flor de Nube que poseas!",
  str_story_banner_5004 = "Múltiples misiones en el evento. Completa más misiones y obtén más recompensas.",
  str_story_banner_5005 = "¡Usa los Pétalos de Flor de Nube para <color=#FFB400>Dibujos de la Suerte</color>! <color=#FFB400>Consigue un premio al azar</color> en la reserva de cada sorteo.",
  str_story_banner_5006 = "Hay 5 quinielas, cada una con un gran premio. Desbloquea la siguiente reserva cuando consigas el <color=#FFB400>gran premio</color>.",
  str_story_banner_5007 = "¡Entre más pétalos de flor de nube tengas, más recompensas tendrás!",
  str_story_banner_5008 = "¡Consulta las reglas del evento aquí!",
  str_story_banner_5010 = "Permítanme presentarles el método de pesca.",
  str_story_banner_5011 = "Bueno, eso es todo lo que necesitas saber sobre la pesca. Ahora, ¡comencemos el desafío!",
  str_story_banner_40301 = "¡Aquí vienen de nuevo! ¡Vengan junto a mí!",
  str_story_banner_40311 = "¡No es mi culpa! ¡No es mi culpa!",
  str_story_banner_40321 = "¡Hermana pequeña!",
  str_story_banner_40322 = "...",
  str_story_banner_40323 = "¡Las Eclipsites se dirigen directamente a Eve! ¡Deprisa, no podemos dejar que Eve sufra más de lo que ya ha sufrido!",
  str_story_banner_40324 = "¡Ni siquiera... pienses en... herir... a mi hermana!",
  str_story_banner_501401 = "¡Aléjate de mi hermana!",
  str_story_banner_501402 = "¡Tu hermana está fuera de control, al igual que Entrañas!",
  str_story_banner_501403 = "Si no encontramos una salida pronto, seremos enterrados aquí...",
  str_story_banner_501404 = "¿Qué Entrañas? ¡No entiendo nada de lo que dices!",
  str_story_banner_501405 = "No nos culpes por ser rudos si vas a seguir así...",
  str_story_banner_501406 = "Nooo... Gre... tel...",
  str_story_banner_501407 = "Lo siento, no tengo opción... ¡Rápido, vamos a por el otro también!",
  str_story_banner_501501 = "Hola, mi amigo caelestita. Vigila nuestro entorno por mí.",
  str_story_banner_501502 = "Espera el momento adecuado y elige una habilidad para avanzar.",
  str_story_banner_501503 = "Haré un quemado para volar un poco de arena. Eso les dará una lección a los enemigos cercanos antes de seguir adelante.",
  str_story_banner_501504 = "Eso es todo. Fácil, ¿verdad?",
  str_story_banner_501505 = "Hmm... siguen viniendo. ¡Que molesto! Sin embargo, je, el enemigo ya está dentro del alcance.",
  str_story_banner_501506 = "¿Quieres tirar algunos juguetes que serán muy dolorosos de pisar?",
  str_story_banner_501507 = "Selecciona una habilidad para bombardear o lanzar misiles al enemigo.",
  str_story_banner_501508 = "¡Apunta antes de tirar o te tiro del auto!",
  str_story_banner_501509 = "Fleur me dijo que ha hecho un pequeño dispositivo que podría cambiar a Lumina.",
  str_story_banner_501510 = "Pero los aurorianos realmente no pueden ver el flujo de Lumina, así que me reí de su cara en respuesta.",
  str_story_banner_501511 = "Mirando hacia atrás, podría haber sido un regalo para ti.",
  str_story_banner_501512 = "Selecciona la habilidad Airdrop. Elija una ubicación para lanzar el lanzamiento aéreo allí.",
  str_story_banner_501601 = "¡Ejem! W-Bienvenido al juego <color=#FFB400>Chocar y quemar</color>.\nSí, tú, tú ahí mismo... ¡Oye! ¿Por qué la violencia?",
  str_story_banner_501602 = "Puedo ser un Eclipsite, ¡pero no soy tu enemigo! Tengo una tarea especial para ti:\n<color=#FFB400>¡Comanden a nuestros camaradas de Eclipsite!</color>\n¿Por qué estás tan sorprendido? Admítelo, has querido hacer esto desde hace mucho tiempo, ¿no es así?",
  str_story_banner_501603 = "Incluso el legendario Eclipsite <color=#FFB400>señor Augean</color> está aquí para ayudar\n¡No hay forma de que perdamos esta vez!",
  str_story_banner_501604 = "¡Vamos, ayúdanos a <color=#FFB400>eliminar el coche de carreras Rediesel Wrench</color> y ganar esto juntos!",
  str_story_banner_501605 = "E-Esto aquí muestra el ATK y HP del enemigo,\ny diré que es una manera bastante fácil de evaluar si estás preparado para el desafío.",
  str_story_banner_501606 = "<color=#FFB400>Tocar a un enemigo auroriano muestra su próxima acción.</color>",
  str_story_banner_501607 = "<color=#FFB400>Los aurorianos suelen apuntar a la unidad enemiga más cercana.</color>",
  str_story_banner_501608 = "Pero ellos <color=#FFB400>¡Solo puede moverse en mosaicos de su propio elemento!</color>\nMantenga su distancia y haga todo lo posible para no dejar que nos lastimen.",
  str_story_banner_501609 = "¡Pasemos a la acción!",
  str_story_banner_501610 = "¡E-Eso es asombroso!",
  str_story_banner_501611 = "Gracias a la habilidad especial de Lord Augean,\n<color=#FFB400>derrotar a un Aurorian refresca nuestro ACT, permitiéndonos actuar una vez más.</color>",
  str_story_banner_501612 = "¡Todo depende de ti ahora!",
  str_story_banner_501613 = "¡Guau! ¡Chasm se ha unido al equipo!\n¡Va a explotar solo y se llevará al enemigo con él!",
  str_story_banner_501614 = "Muy bien, ¡veamos cuán poderosa es su explosión!",
  str_story_banner_501615 = "Abismo <color=#FFB400>inflige daño en un área en forma de diamante a su alrededor.</color>\nTambién <color=#FFB400>rompe el azulejo sobre el que está parado.</color>",
  str_story_banner_501616 = "¡Mira, los Longhooks también se han unido a la batalla!",
  str_story_banner_501617 = "Espera un minuto. ¿Por qué estos tipos parecen estar aturdidos?\nSus anzuelos no llegan tan lejos como de costumbre.",
  str_story_banner_501618 = "<color=#FFB400>Pueden enganchar y arrastrar objetivos hasta 3 mosaicos frente a ellos.</color>",
  str_story_banner_501619 = "Aún así,\nen ciertas circunstancias, <color=#FFB400>enganchar a otros Eclipsites puede ayudar a cambiar las cosas.</color>",
  str_story_banner_501620 = "Aquí hay un consejo para ti. Después de que todos nuestros Eclipsites completen sus movimientos,\n<color=#FFB400>Los aurorianos atacarán a la unidad enemiga más cercana.</color>\nCuando hay varios eclipses cerca, <color=#FFB400>apuntarán al que tenga el HP más bajo.</color>",
  str_story_banner_501621 = "Incluso cuando hay otros eclipses dentro del alcance,\nlos aurorianos cazarán implacablemente al más cercano. Los aurorianos son un grupo aterrador...",
  str_story_banner_501622 = "¡Pero puedes usar este rasgo contra ellos! Al sacrificar a un compañero de equipo,\npuede permitir que otros Eclipsites se acerquen a ellos.",
  str_story_banner_501630 = "Cuidado, PlayerName. El ambiente aquí no se siente bien.",
  str_story_banner_501631 = "Esos monstruos en particular tienen un aspecto extraño.",
  str_story_banner_501632 = "Las reglas del Sistema de Sanidad se aplican a esta batalla. Cuando cae Cordura, se activan los efectos correspondientes.",
  str_story_banner_501633 = "Algunos Aurorianos parecen ser capaces de afectar la batalla de manera similar. Sus efectos de habilidad también se ven afectados por los puntos de cordura.",
  str_story_banner_501634 = "Recordar. Mantén la calma y afronta la situación con calma.",
  str_story_banner_501635 = "Parece que hay reglas de batalla adicionales.",
  str_story_banner_502701 = "PlayerName, la batalla aquí va a ser un poco diferente.",
  str_story_banner_502702 = "Ver el <color=#FFB400>cuenta regresiva</color> ¿allí?",
  str_story_banner_502703 = "Es un temporizador que muestra el día y la noche. Cuando termine la cuenta regresiva, el día y la noche se intercambiarán.",
  str_story_banner_502704 = "Este eclipse no se mueve, pero...",
  str_story_banner_502705 = "¡¿Mis flechas no lo lastiman en absoluto?!",
  str_story_banner_502706 = "Déjame ver si hay algo en el manual sobre este Eclipsite...",
  str_story_banner_502707 = "¡Ajá! Según el manual, este Eclipsite se debilita durante el día y entra en un estado defensivo.",
  str_story_banner_502708 = "Durante este período, dejará de atacar y se centrará en la defensa, esquivando la mayoría de los ataques.",
  str_story_banner_502709 = "Y sólo puede ser dañado por <color=#FFB400>ataques de área grande</color>!",
  str_story_banner_502710 = "¡Cambiemos al Capitán y derrotémoslo con un ataque de área grande!",
  str_story_banner_502711 = "PlayerName, el día y la noche han cambiado.",
  str_story_banner_502712 = "Parece que el Eclipsite también está cambiando. ¡Está empezando a moverse!",
  str_story_banner_502713 = "Cuidadoso, PlayerName!",
  str_story_banner_502714 = "¡Te dejo el resto a ti!",
  str_story_banner_502801 = "¿Qué hace un Eclipsite de alto nivel aquí?",
  str_story_banner_502802 = "No hay nada en el manual sobre el manejo de tal Eclipsite...",
  str_story_banner_502803 = "Supongo que nuestras manos están atadas. ¡Tendremos que encontrar una manera de salir de aquí!",
  str_story_banner_502804 = "Mirar, PlayerName, creo que esa es la salida!",
  str_story_banner_502805 = "Parece que se va a derrumbar en cualquier momento. ¡Hagamos una carrera por ello!",
  str_story_banner_502806 = "¡No dejes que Eclipsite colapse la salida!",
  str_story_banner_502901 = "Esta cosa... ¡Ha cambiado!",
  str_story_banner_502902 = "Parece que también se ha vuelto más fuerte...",
  str_story_banner_502903 = "Míralo, PlayerName.",
  str_story_banner_503001 = "Este olor desagradable... ¿Qué es?",
  str_story_banner_503002 = "Mi poder se debilita a medida que me acerco.",
  str_story_banner_503003 = "Por favor, trate de evitarlo si es posible.",
  str_story_banner_5016411 = "Lenore te vio venir, PlayerName. Los eclipses en la distancia representan una seria amenaza.",
  str_story_banner_5016412 = "Deja que Lenore los acabe todos de una sola vez. En caso de insuficiencia <color=#FFB400>puntos de cordura</color>, <color=#FFB400>HP</color> puede deducirse en su lugar.",
  str_story_banner_5016413 = "Bien hecho, PlayerName.",
  str_story_banner_5016414 = "Los Eclipsites restantes están dispersos por todo el lugar, pero está bien. Lenore se vuelve más fuerte cuando <color=#FFB400>la cordura cae a 0</color>.",
  str_story_banner_5016415 = "PlayerName, guía a Lenore para lanzar un Chain Combo y acabar con los Eclipsites restantes.",
  str_story_banner_5016416 = "¿Mmm? espejismos? Normalmente no aparecerán hasta que nuestra <color=#FFB400>Sanity</color> sea bastante baja. ¡Ah ah ah! Podríamos colapsar pronto.",
  str_story_banner_5016417 = "Bostezo... Estas molestas criaturas no son más que cebos.",
  str_story_banner_5016418 = "Un sentimiento maravilloso... Esta fuerza misteriosa... ¡Hahah! ¡Vamos a matarlos a todos!",
  str_story_banner_5016419 = "Noche blanca en lo alto... ¿Dónde estoy? Estoy teniendo un gran dolor de cabeza... ¿Nos hemos quedado sin <color=#FFB400>cordura</color> ¿ya?",
  str_story_banner_5016420 = "¡Ah ah ah! No te preocupes. Puedo ayudar a aliviar su dolor.",
  str_story_banner_5016421 = "¿Te sientes mejor? Solo déjame ayudarte a restaurar algo de <color=#FFB400>Sanity</color> si es necesario.",
  str_story_banner_50303 = "Parece que tenemos todos los materiales necesarios. ¡Cachero!",
  str_story_banner_50402 = "Este es el banco de trabajo de Hyacinth Tower. Aquí puedes construir todo tipo de edificios y muebles. ¡Cachero!",
  str_story_banner_50602 = "¡Parece que cuatro Aurorianos pueden establecerse aquí, y los Aurorianos establecidos también mejorarán su Afinidad! ¡Intenta invitar a la Sra. Blanc!",
  str_story_banner_50701 = "Aquí puedes ver el nivel de Cloud Gardens.",
  str_story_banner_50801 = "¡Hay tantos peces en el río! ¡Empecemos a pescar!",
  str_story_banner_50804 = "¡Hemos pescado un pez! ¡Date prisa y enróllalo!",
  str_story_banner_50901 = "¡Bienvenido a la tienda Cloud Gardens, Chubb! ¡Aquí, puedes intercambiar productos y completar pedidos para ganar Cloud Gardens Rock Shards, Chubb!",
  str_story_banner_51001 = "Chubb, Chubb! ¡Te enseñaré a plantar un árbol!",
  str_story_banner_9001 = "Chubb, Chubb!",
  str_story_banner_9002 = "¡Por favor, recoge madera primero, Navegante!",
  str_story_banner_9003 = "Madera, madera. Chubb, Chubb!",
  str_story_banner_9004 = "Parece que necesitamos más minerales...",
  str_story_banner_9005 = "Mineral, mineral. Chubb, Chubb!",
  str_story_banner_9006 = "¡Tenemos todos los materiales! ¡Déjame encargarme de esto, Chubb!",
  str_story_banner_9007 = "¡Intentemos construir un dormitorio Gardens en Hyacinth Tower!",
  str_story_banner_9008 = "¡Vamos a colocar el dormitorio!",
  str_story_banner_9009 = "¡Invitemos a la Sra. Blanc a mudarse al dormitorio ahora!",
  str_story_banner_9010 = "¡Ve a hablar con la Sra. Blanc y dale la bienvenida!",
  str_story_banner_9011 = "Hola navegante. Parece Vice tiene algo que decirte.",
  str_story_banner_9012 = "Puedes pescar justo a mi lado. ¡Darle una oportunidad!",
  str_story_banner_9013 = "Hora de pescar y relajarse, Navegante.",
  str_story_banner_9014 = "Una vez que hayas reunido todos los materiales, ve a Chubb y repara la tienda.",
  str_story_banner_9015 = "Parece que alguien te está esperando en la tienda, navegante.",
  str_story_banner_9016 = "¡Envíe un pedido al Chubb Merchant!",
  str_story_banner_9017 = "¿Has completado el pedido, navegante?",
  str_story_banner_9018 = "¡Pedido completado! Hablar con Vice ¡ahora!",
  str_story_banner_9019 = "¡Ve a Hyacinth Tower y construye una parcela de Land of Fertility!",
  str_story_banner_9020 = "¡Coloca la tierra de la fertilidad en un terreno baldío!",
  str_story_banner_9021 = "¡Intentemos criar y cosechar un árbol único!",
  str_story_banner_9022 = "¡Date prisa, ve a buscar un lugar adecuado para reclamar!",
  str_story_banner_503501 = "Una victoria completa, PlayerName!",
  str_story_banner_503502 = "Si bien fue una emergencia, ¡logramos salir de ella sin un rasguño!",
  str_story_banner_503503 = "¿PlayerName?",
  str_story_banner_503504 = "C-Carleen! PlayerName...",
  str_story_banner_503505 = "...tampoco me ha respondido.",
  str_story_banner_503506 = "Si puedes sentirnos, PlayerName, ¡responde ahora!",
  str_story_banner_503507 = "¡PlayerName...!",
  str_story_banner_503601 = "Si mal no recuerdo, este es el camino al Núcleo Central.",
  str_story_banner_503602 = "Un gran número de Eclipsites han irrumpido en la Torre del Retorno.",
  str_story_banner_503603 = "Sería difícil derrotarlos a todos en nuestra situación actual.",
  str_story_banner_503604 = "Pero no debería ser difícil simplemente escapar de ellos.",
  str_story_banner_504001 = "Las etapas del Modo Caja de Pandora son más difíciles que el Modo Normal. Por favor, esté listo.",
  str_story_banner_504002 = "Al mismo tiempo, el modo Pandora's Box tiene condiciones especiales completas que requieren la cooperación de varios equipos.",
  str_story_banner_5017311 = "Es casi como una etapa de supervivencia. Las oleadas de monstruos parecen interminables...",
  str_story_banner_5017312 = "Eso suena como Barton! Gronru, ¿se enteró que?",
  str_story_banner_5017313 = "Creo que sí... ¿Está bien?",
  str_story_banner_5017314 = "Si es él... No hay necesidad de preocuparse.",
  str_story_banner_5017315 = "Esa cosa de la que te estaba hablando. ¿Has descubierto algo?",
  str_story_banner_5017316 = "Bueno, según mi etapa experiencias claras...",
  str_story_banner_5017317 = "¡Esto no es un juego!",
  str_story_banner_5017318 = "Estará bien. A juzgar por los patrones de estos eclipses, no quedarán demasiados.",
  str_story_banner_5017319 = "Si ese es el caso, eliminémoslos a todos.",
  str_story_banner_5017320 = "Te enviaré sus posiciones y te ayudaré.",
  str_story_banner_5017321 = "¡Es hora de brillar, Star-Piercing Spear!",
  str_story_banner_5017322 = "¡Hay muchos eclipses aquí! Me pregunto si el Gran Mariscal está bien. Probablemente no tengamos que preocuparnos.",
  str_story_banner_5017323 = "Oh, me has rodeado. Me gustan esas probabilidades. ¡Hora de probar mi nuevo juguete!",
  str_story_banner_5017324 = "¡Esto se siente increíble! Mientras sigamos luchando, nuestro poder seguirá creciendo...",
  str_story_banner_5017325 = "¡Vamos! ¡Vamos!",
  str_story_banner_5018311 = "¡Hay tantos eclipses en el camino! My Secret Trove se encargará de esto.",
  str_story_banner_5018312 = "Eso es más lejos de lo que pretendía. Déjame recuperar mi paraguas y acabar con los eclipses restantes.",
  str_story_banner_5018321 = "Um... El enemigo está un poco lejos de mí... Manae, te lo dejo a ti.",
  str_story_banner_5019301 = "Hay más enemigos entrantes, ¡hagámoslo!",
  str_story_banner_5019302 = "¡Ahora es el momento! Utilizar el <color=#FFB400>Habilidad especial</color>!",
  str_story_banner_5019303 = "Hay muchos enemigos del bosque. ¡Cambia al capitán ahora y enséñales una lección!",
  str_story_banner_5020301 = "Parece que no hay una ruta para movernos hacia el monstruo y atacar.",
  str_story_banner_5020302 = "¡Eso no me detendrá! El misil de flecha solar de este mecha dinámico puede abrir un camino. ¡Pruébalo ahora!",
  str_story_banner_5020303 = "¡Se han eliminado los obstáculos! ¡Acaba con ellos de una sola vez!",
  str_story_banner_5020311 = "¡Qué error de cálculo! De hecho, me dolieron las tácticas de multitud de los Eclipsites.",
  str_story_banner_5020312 = "No puedes quedar atrapado en una guerra de desgaste con estos eclipses. Debes curar tus heridas e irte lo antes posible.",
  str_story_banner_5020313 = "Todavía puedes lanzar Combustión unas cuantas veces más. Obtenga el vendaje, luego únase a todos los demás rápidamente.",
  str_story_banner_5020314 = "Muy bueno. Una vez que obtenga los vendajes restantes a través de Combustión, debe ser lo suficientemente fuerte como para derrotar a todos los enemigos. ¡Vamos, inútiles Eclipsitas!",
  str_story_banner_5020321 = "¿Q-Qué es este lugar?",
  str_story_banner_5020322 = "Cuidado, debemos haber sido arrastrados a un espacio que creó el arma de la civilización antigua.",
  str_story_banner_5020323 = "¿Es este el \"momento del enfrentamiento\" que acaba de mencionar?",
  str_story_banner_5020324 = "debe ser ¡Prepárate!",
  str_story_banner_5020325 = "Vamos. ¡Esta es la última batalla!",
  str_story_banner_5020326 = "Le prometí a Elvis cumplir su deseo y reactivar Windstone.",
  str_story_banner_5020327 = "¡Bestias! ¡Ni se te ocurra dar un paso más!",
  str_story_banner_5020328 = "Elvis, ¿cómo te va por tu lado?",
  str_story_banner_50213211 = "Aunque todo es para las bestias maravillosas, ¿no crees que las cosas han sido demasiado difíciles? ¿Qué opinas, Kyllo?",
  str_story_banner_50213212 = "Lo...",
  str_story_banner_50213213 = "¡Sí! ¡Pero debo tener éxito esta vez para impresionar a mi amo!",
  str_story_banner_50213214 = "¡Lo!",
  str_story_banner_50213215 = "¡Guau! ¡De repente hay tantos eclipses!",
  str_story_banner_50213216 = "Oh, Kyllo debe tener hambre pronto. ¡Termina con ellos rápidamente para que podamos volver y tener un festín!",
  str_story_banner_50213217 = "¡Lo!",
  str_story_banner_50213218 = "¿Qué es esto? ¿Por qué hay una marca de caza allí? Que extraño. ¿Podría haberse caído por accidente cuando estaba jugando en Soroz? Oh bueno, es mejor así. ¡Vamos, Kyllo!",
  str_story_banner_50213219 = "Causamos algunos estragos, ¿verdad, Kyllo?",
  str_story_banner_50213220 = "¡Lo! ¡Lo!",
  str_story_banner_50213221 = "Se ha rociado agua por todas partes... Bueno, todavía parece haber muchos eclipses. ¡Coloquemos algunas marcas de caza!",
  str_story_banner_50213222 = "¡De repente tengo una idea divertida! ¡Kyllo, vamos a cargar!",
  str_story_banner_50213311 = "¡Hace tanto calor! ¿Quieres refrescarte?",
  str_story_banner_50213312 = "¿Ves los eclipses de allí? Están parados en mi marca Sunshower. ¡Déjame activarlo para crear un manantial refrescante!",
  str_story_banner_50213313 = "¡Los eclipses han volado por los aires! Tralala!",
  str_story_banner_50213314 = "¡Mirar! Aparecerá una nueva marca en una loseta que tenga 3 marcas de lluvia de sol a su alrededor.",
  str_story_banner_50213315 = "¡Excelente! ¡Vamos a derrotar a los enemigos con mi pistola de agua ahora en una pelea de pistolas de agua!",
  str_story_banner_50213401 = "¡Muchos Eclipsites aparecieron en el teatro sin nombre durante una magnífica actuación! Nadie podía decir si esto era una ilusión causada por la pérdida gradual de la cordura o una amenaza real, pero Jeno no parecía afectado de ninguna manera en el escenario.",
  str_story_banner_50213402 = "Demos la bienvenida a nuestro estimado invitado, PlayerName, para usar el Origin Deck conmigo en el escenario!",
  str_story_banner_50213403 = "Al mismo tiempo, también quiero invitar a Paloma, ¡nuestra otra invitada de hoy!",
  str_story_banner_50213404 = "¡Aurorianos o Eclipsitas, todos han venido a apoyarme!",
  str_story_banner_50213405 = "Al principio, sólo había luz. Luego, estaban el sol, la luna y las estrellas. Cuando su suave luz se proyecta sobre las cartas, da a luz a todas las cosas. De ahí el nombre \"Origen\".",
  str_story_banner_50213406 = "Ahora es el momento de mostrar su poder.",
  str_story_banner_50213407 = "Primero, necesitamos obtener muchas cartas. Cuidado, aquellos que deseen espiar los secretos del Origen pueden perder la cordura...",
  str_story_banner_50213408 = "Una tarjeta más. Solo perderé un poco más de cordura.",
  str_story_banner_50213409 = "¡Más! Puedo tomar más que esto.",
  str_story_banner_50213410 = "Esta es la biblioteca. Aquí se muestra el número de cada tipo de tarjeta.",
  str_story_banner_50213411 = "Vaya aquí para ingresar a la pantalla de selección de la plataforma de origen.",
  str_story_banner_50213412 = "Las tarjetas Solar, Lunar y Cósmica de la izquierda se pueden arrastrar a las ranuras para tarjetas. Se activará un efecto correspondiente cuando se coloquen cartas de origen en las 3 ranuras.",
  str_story_banner_50213413 = "Ahora seleccione 1 tarjeta de cada tipo y colóquelas en las ranuras para tarjetas.",
  str_story_banner_50213414 = "La combinación de Tránsito Astronómico se forma cuando las 3 cartas son de diferentes tipos, lo que aumenta permanentemente el ATK del miembro en la parte posterior del equipo.",
  str_story_banner_50213415 = "PlayerName, por favor haz que Paloma sea la capitana.",
  str_story_banner_50213416 = "Ahora ingrese a la pantalla de selección de Origin Deck.",
  str_story_banner_50213417 = "Esta vez formemos la combinación del Cúmulo Luminoso. Coloque 3 tarjetas del mismo tipo en las ranuras para tarjetas.",
  str_story_banner_50213418 = "Paloma ahora puede recibir 2 efectos combinados de Origin Deck, lo que aumentará enormemente su poder de combate. Esto es en lo que destaco.",
  str_story_banner_50213419 = "Hay 1 combinación más. Recuerda usarlo cuando quieras recuperar la cordura.",
  str_story_banner_50213420 = "PlayerName, el escenario ahora es tuyo. Mantenga el espectáculo en marcha con cualquier actuación que desee.",
  str_story_banner_507401 = "¡Tranquila, Casta!",
  str_story_banner_507402 = "¡¿En serio me estás diciendo que me calme con el asesino de Matilda justo en frente de mí?!",
  str_story_banner_507403 = "¡Lo diré una última vez, sal de mi camino!",
  str_story_banner_507404 = "Parece que tendremos que hacer esto de la manera difícil...",
  str_story_banner_50223211 = "¡Cuidado! Un eclipse nos está emboscando allí.",
  str_story_banner_50223212 = "Déjame preparar mis armas, luego podemos acercarnos y sorprenderlos con lo que tenemos.",
  str_story_banner_50223213 = "Los mosaicos verdes y los mosaicos mejorados pueden ayudarme a encontrar los puntos débiles del enemigo. Por cada 6 puntos encontrados, mi siguiente ataque se volverá más poderoso.",
  str_story_banner_5022321301 = "Si una ficha cumple ambas condiciones, puedo encontrar el doble de puntos débiles, así que intenta moverte por el camino de ambas fichas.",
  str_story_banner_50223214 = "¡Se alcanzó el límite de Trigger Point! Las armas están calientes de nuevo. ¡Usa tu habilidad activa de nuevo y elimina a los monstruos que te rodean!",
  str_story_banner_50223111 = "Todavía hay tantos enemigos, pero aún no están dentro del alcance de mi fuego pesado...",
  str_story_banner_50223112 = "Sin una línea clara de ataque, no hay mucho que pueda hacer.",
  str_story_banner_50223113 = "Je... ¡Si no hay una línea de ataque, tendremos que hacer una nosotros mismos! ¡Expansión de balas!",
  str_story_banner_50223114 = "¡El enemigo no tiene adónde huir! ¡Es hora de acabar con ellos con mi Heavy Fire!",
  str_story_banner_41000111 = "De acuerdo con la inteligencia... Esto debería ser la ciudad subterránea–¡Achoo! Parece que nadie ha venido aquí por un tiempo, así que tenga cuidado al explorar.",
  str_story_banner_41000112 = "Está muy bien disimulado. Hubiera sido tan difícil encontrarlo si Siobhan no estuviera aquí.",
  str_story_banner_41000113 = "¡Creo que huelo algo asqueroso! ¡Maullar!",
  str_story_banner_41000114 = "¡Oye! ¡Los Eclipsites aquí parecen haber dominado una nueva y extraña habilidad!",
  str_story_banner_41000115 = "Es un Wormgate. Así fue como llegaron y atacaron la ciudad subterránea.",
  str_story_banner_41000116 = "Suena peligroso, miau.",
  str_story_banner_41000117 = "Parece que siguen surgiendo eclipses, por lo que debemos ser cautelosos.",
  str_story_banner_41000121 = "Uno, dos... Hay mucho por venir.",
  str_story_banner_41000122 = "Busquemos un terreno favorable antes de que aparezcan.",
  str_story_banner_41000123 = "¡Vamos allí juntos primero!",
  str_story_banner_41000131 = "Menos mal que vinimos aquí, o de lo contrario estaríamos rodeados por esos eclipses.",
  str_story_banner_41000132 = "Hay demasiados eclipses. Tenemos que luchar contra ellos y encontrar una salida.",
  str_story_banner_41000133 = "¡Que comience la batalla!",
  str_story_banner_41000141 = "¡Ahhh! ¡Mi garganta!",
  str_story_banner_41000142 = "¿Es este... el gas nocivo mencionado en el contrato?",
  str_story_banner_41000143 = "No te preocupes. Todavía queda mucho tiempo hasta que nos vuelva locos.",
  str_story_banner_41000151 = "Creo que veo una salida.",
  str_story_banner_41000152 = "De acuerdo con el plano de antes, ¡ese camino debería conducir a una habitación con un dispositivo de ventilación!",
  str_story_banner_41000161 = "No parece que el camino por delante vaya a ser fácil de atravesar...",
  str_story_banner_41000162 = "Este es el momento perfecto para sacar a relucir PlayerName¡El equipo más nuevo! ¡Maullar!",
  str_story_banner_41000163 = "¡Abrojos furiosos!",
  str_story_banner_41000164 = "En realidad trajiste eso. Estaba pensando en estudiarlo más tarde...",
  str_story_banner_41000165 = "Ejem... De todos modos, deja PlayerName úsalo para cambiar el Lumina. ¡Correremos hasta allí de un tirón!",
  str_story_banner_41000171 = "PlayerName, es bastante simple de usar. ¡Solo tíralo, miau! ¡Incluso Revy puede usarlo correctamente!",
  str_story_banner_41000172 = "Que bueno escucharlo.",
  str_story_banner_41000173 = "¿Qué quieres decir con \"incluso Revy puede usarlo correctamente\"...",
  str_story_banner_41000181 = "¡Parece estar funcionando! Ahora, PlayerName¡Necesitamos que nos guíes!",
  str_story_banner_41000211 = "Solo déjanos el resto a nosotros, Vice.",
  str_story_banner_41000212 = "Muy bien, estoy confiando en ti para proteger PlayerName.",
  str_story_banner_41000213 = "Relájese, todo debería estar bien con el oficial técnico Gronru y Migard aquí. Ustedes descansen un poco por ahora.",
  str_story_banner_41000214 = "Advertencia. Extraña piedra detectada cerca.",
  str_story_banner_41000215 = "Esa debe ser la Piedra Halo... Pero, ¿qué está haciendo aquí? ¿No debería estar encerrado en el nivel más bajo del laboratorio de investigación?",
  str_story_banner_41000216 = "¿Será que alguien ya ha estado aquí?",
  str_story_banner_41000217 = "Eso es imposible. Lo más probable es que haya sido traído aquí sin querer por un eclipse. Sin alguien que los mande, simplemente se mueven y actúan indiscriminadamente.",
  str_story_banner_41000221 = "Bueno, menos mal que están aquí. ¡Jeje, activemos esta cosa!",
  str_story_banner_41000231 = "Parece bastante útil. Al producirlo en masa, podríamos resolver muchos de nuestros problemas en el campo de batalla...",
  str_story_banner_41000232 = "Lamento decírselo, jefe, pero creo que todavía está en las primeras fases de investigación. Como reliquia de la antigua civilización, es algo inestable.",
  str_story_banner_41000233 = "¡Así es! Me di cuenta de que si el Lumina es demasiado complejo, ¡falla!",
  str_story_banner_41000241 = "Advertencia. Enemigos acercándose.",
  str_story_banner_41000242 = "Realmente no podemos tomar un descanso, ¿verdad?",
  str_story_banner_41000243 = "¡Fuerzalos de vuelta por ahora! ¡Todos, ataquen!",
  str_story_banner_41000251 = "Advertencia. Piedra desagradable detectada.",
  str_story_banner_41000252 = "Eso ya lo sabemos. ¿Vas a repetirte cada vez?",
  str_story_banner_41000253 = "Esa piedra parece estar suprimiendo nuestras habilidades... Presta mucha atención a eso, PlayerName!",
  str_story_banner_41000261 = "Confirmado. Incapaz de usar ciertas habilidades.",
  str_story_banner_41000262 = "Es verdad...",
  str_story_banner_41000263 = "Si esto fuera un juego de algún tipo, ¡nuestro mejor movimiento sería alejarnos de él!",
  str_story_banner_41000271 = "Me siento mucho mejor ahora. Incluso el aire parece mucho más claro.",
  str_story_banner_41000272 = "Pero con esa piedra bloqueando el camino, vamos a tener dificultades para progresar.",
  str_story_banner_41000273 = "Interesante. Toma, déjame intentar algo.",
  str_story_banner_41000281 = "¡Guau! ¡Parece que mientras estemos fuera de su área de efecto, nuestros poderes no se verán afectados!",
  str_story_banner_41000282 = "Por cierto. Me aseguré de mantener cierta distancia justo ahora antes de atacar.",
  str_story_banner_41000291 = "¡Allá!",
  str_story_banner_41000292 = "Parece que de esta manera conduce a un ventilador. ¡Estamos a punto de atravesar este piso!",
  str_story_banner_41000293 = "Suspiro... ¿Podrías dejar de tratar la batalla como si fuera un juego? No importa. PlayerName, por favor llévanos allí rápidamente.",
  str_story_banner_11200202 = "PlayerName, hemos recibido una solicitud de la Federación Illumina para investigar Entrañas π.",
  str_story_banner_11400101 = "¡El laboratorio de Axelia ha comenzado! ¡Recoge piezas de desecho y ayuda a Axelia a completar sus experimentos!",
  str_story_banner_11500401 = "Navigator, apareció un nido cerca del Territorio Secreto, y se han detectado una gran cantidad de Eclipses. ¡Debemos ocuparnos de ellos lo antes posible!",
  str_story_banner_11500701 = "¡Navegador! ¡Ha aparecido un enorme enjambre de eclipses! ¡La única forma en que saldremos victoriosos aquí hoy es si repelemos todas las olas de Eclipsite!",
  str_story_banner_11500702 = "¡Hemos despejado la primera oleada de eclipses! Cada vez que luches contra una ola de Eclipsites, obtendrás una Reliquia como recompensa para fortalecer tu poder de combate en las siguientes batallas. ¡Ahora, selecciona una reliquia!",
  str_story_banner_11500703 = "¡Has derrotado al jefe! Un nuevo compañero puede unirse a tu equipo para ayudarte en la batalla. ¡Ahora, selecciona un Aurorian!",
  str_story_banner_11500704 = "Un auroriano que se una a ti en la batalla puede conectar fichas para luchar, lanzar combos en cadena y usar habilidades activas, al igual que el resto de tu equipo.",
  str_story_banner_11500705 = "¡Solo puedes avanzar una vez que hayas eliminado suficientes eclipses!",
  str_story_banner_11500706 = "Esta será una dura pelea... Pero no te preocupes, ¡en esta batalla tendrás poderosos compañeros aurorianos que te ayudarán a salir victorioso!",
  str_story_banner_11500707 = "¡Ahora es el momento de prepararse para luchar!",
  str_story_banner_523500201 = "Es hora de informar a la señorita Nina. Todo va bien con la casa embrujada por ahora.",
  str_story_banner_523500202 = "Me pregunto cómo le ha ido a la señorita Nina recientemente. Sanae debería cuidarla bien.",
  str_story_banner_523500203 = "Hmm... Eclipses, que criaturas tan patéticas. Es una pena que no tenga tiempo para ponerlos a dormir en este momento.",
  str_story_banner_523500204 = "Un mayordomo perfecto nunca debe llegar tarde. Debo darme prisa.",
  str_story_banner_523500301 = "Haciéndome ir a los suburbios para encontrar una billetera perdida o algo así, ¿por qué Dayna todavía me trata como a una niña pequeña?",
  str_story_banner_523500302 = "La cartera... La cartera... ¡Ah! ¡Aquí está!",
  str_story_banner_523500303 = "Jeje, debería pedirle otra tarea después de que regrese. ¡Algún día me convertiré en un verdadero espadachín si sigo así!",
  str_story_banner_523500304 = "¿¿¡¡Que!!?? ¡¿Cuándo aparecieron tantos eclipses detrás de mí?!",
  str_story_banner_523500305 = "¡Está bien! Sadie! Haz lo que sueles hacer durante el entrenamiento... Haz lo que sueles hacer durante el entrenamiento... Haz lo que sueles hacer durante el entrenamiento...",
  str_story_banner_523500306 = "Pelota voladora-!",
  str_story_banner_523500307 = "¡Funcionó! ¡Estoy un paso más cerca de convertirme en un espadachín! ¡Me ocuparé de ti rápidamente y le contaré a Dayna todo sobre mi movimiento genial!",
  str_story_banner_523500101 = "Es hora de informar a la señorita Nina. Todo va bien con la casa embrujada por ahora.",
  str_story_banner_523500102 = "¡Guau! ¿Qué tiene de malo este lugar? ¿Por qué de repente hay eclipses a mi alrededor? ¡Esto es aterrador!",
  str_story_banner_523500103 = "Mantén la calma... Mira, hay otro conjunto deslumbrante allí.",
  str_story_banner_523500104 = "¡Puedo teletransportarme allí primero, ajustar mi posición y destruirlos!",
  str_story_banner_523500105 = "¡Tada! ¡Mira mi deslumbrante entrada!",
  str_story_banner_523500106 = "Este camino nos permite movernos entre dos conjuntos deslumbrantes. Invocaremos una nueva matriz deslumbrante mientras atacamos los Eclipsites y conectaremos estas dos matrices deslumbrantes.",
  str_story_banner_523500107 = "La deslumbrante variedad se ha vuelto más grande. Destruyamos estos terroríficos eclipses ahora.",
  str_story_banner_524300101 = "¡Esto es malo! No solo las tropas están separadas, ahora también tenemos eclipses.",
  str_story_banner_524300102 = "Simplemente lo llamaremos un cambio de humor.",
  str_story_banner_524300103 = "¡Axelia, es tu turno!",
  str_story_banner_524300104 = "Copiar. Activando el Módulo de Autoridad. Ruta óptima calculada.",
  str_story_banner_524300105 = "Compensaré cualquier falta de curación y potencia de fuego.",
  str_story_banner_524300106 = "En espera, Gran Mariscal.",
  str_story_banner_10130701 = "¡Creo que ya tenemos una conclusión!",
  str_story_banner_10130702 = "¡El simulador funciona mucho más allá de nuestras expectativas!",
  str_story_banner_10130703 = "PlayerName parece haberse fortalecido.",
  str_story_banner_10130704 = "Eso solo se puede confirmar después PlayerName se desconecta del Coloso y finaliza el experimento.",
  str_story_banner_10130705 = "Después de todo, todavía tenemos que comprobar los datos de sus funciones físicas.",
  str_story_banner_10130706 = "Silbido-!!!",
  str_story_banner_10130707 = "¡¿Cómo es eso posible?!",
  str_story_banner_10130708 = "¡E-Los datos del antiguo campo de batalla deben estar corrompidos!",
  str_story_banner_10130709 = "¡Investigadores, escúchenme! ¡Termina el experimento inmediatamente!",
  str_story_banner_10131201 = "Sintiendo temblores desde el suelo.",
  str_story_banner_10131202 = "La próxima desintegración tocará el manto, dislocando y agrietando la superficie.",
  str_story_banner_10131203 = "El campo de batalla virtual está a punto de llegar a su punto de no retorno.",
  str_story_banner_10131204 = "Haré la cuenta regresiva final por ti.",
  str_story_banner_524300201 = "Huff... Los eclipses siguen llegando. ¿Están tratando de agotarme? Y estoy lesionado...",
  str_story_banner_524300202 = "Pero no seré derrotado por sus tácticas.",
  str_story_banner_524300203 = "Elige el camino más largo que puedas recorrer para que pueda perforar sus cuerpos con Australis Spears primero.",
  str_story_banner_524300204 = "Los preparativos preliminares se han completado. Comenzando el tratamiento.",
  str_story_banner_525300201 = "*Bostezos* Parece que tenemos Eclipsites acercándose.",
  str_story_banner_525300202 = "Ese Eclipsite de élite los está protegiendo de ser destruidos.",
  str_story_banner_525300203 = "Je... ¿Crees que estás a salvo escondiéndote todo el camino hasta allí?",
  str_story_banner_525300204 = "¡Ataque! ¡Todos! ¡Mata primero a ese Eclipsite de élite!",
  str_story_banner_525400301 = "¡Vaya! Lola, prometo acompañarte a lo largo de tu entrenamiento especial, ¡siempre y cuando compartas los últimos chismes conmigo!",
  str_story_banner_525400302 = "¡Gracias un montón! ¡Dame un tarro de mi miel favorita también!",
  str_story_banner_525400303 = "¡Negociar! Mira, hay uno realmente difícil justo ahí.",
  str_story_banner_525400304 = "¡No te apresures! ¡Haré que exponga su debilidad primero y luego lo desmontaremos!",
  str_story_banner_525400305 = "Siento que mi precisión ha mejorado. ¡Tu cámara es increíble!",
  str_story_banner_525400306 = "¡Esos eclipses han sido afectados con una marca de replanteo! Si los atacas con un combo en cadena ahora mismo, ¡hará más daño!",
  str_story_banner_5254002011 = "¿¡De dónde vinieron todos estos enemigos!? ¡Pongamos este espectáculo en el camino!",
  str_story_banner_5254002012 = "¡Ni siquiera sabrán qué los golpeó!",
  str_story_banner_5254002013 = "¡Modo Grito de Guerra! ¡Cambio de soprano!",
  str_story_banner_5254002014 = "¡Esta ruta a través de la conexión de mosaico mejorada debería funcionar! ¡Ignora la barricada enemiga y corre al escenario! ¡Necesito saludar a mis fans en plena forma!",
  str_story_banner_52630021 = "Parece que he vuelto al campo de batalla de nuevo.",
  str_story_banner_52630022 = "Aunque la movilidad es un problema, haré todo lo posible para ayudarte.",
  str_story_banner_52630023 = "Y así, el Eclipsite está temporalmente a merced de mi Llama Ancestral.",
  str_story_banner_52630024 = "Por favor, usa mi habilidad para mover el Eclipsite. La Llama Ancestral abrirá un camino.",
  str_story_banner_52630025 = "¡Qué poder tan milagroso! Cuéntanos una historia de esos días pasados cuando todo ha terminado.",
  str_story_banner_52630031 = "Que dolor... PlayerName, no me dijiste que habia eclipses tan molestos como estos!",
  str_story_banner_52630032 = "Si atacamos directamente, los otros Eclipsites se recuperarán.",
  str_story_banner_52630033 = "Déjamelo a mí... ¡Tengo el remedio perfecto!",
  str_story_banner_52630034 = "Ahora bien, este tipo no bajará en esta ronda. ¡Noqueate, viejo!",
  str_story_banner_52630035 = "¡Buen trabajo! No tengo pescado aquí, pero te dejaré probar una lagartija especial a la parrilla más tarde.",
  str_story_banner_52630011 = "Un enjambre de Eclipsites ha abordado la nave. No te asustes.",
  str_story_banner_52630012 = "Usa combos en cadena tanto como puedas para encender mis bengalas de serpiente.",
  str_story_banner_52630013 = "¡Después de encender las tres bengalas de serpiente, puedo usar mi poderosa habilidad activa para desatar la ira del mar sobre ellas!",
  str_story_banner_52630014 = "¡Enciende una bengala de serpiente, continúa haciendo combos y luego enciende el resto! Serpent Flares se puede iluminar más fácilmente durante Aurora Time.",
  str_story_banner_527200401 = "Pequeño navegante, es tu turno de mandarme, quiero decir, Bullock 8.",
  str_story_banner_527200402 = "¡Mi dulce amor! ¡No lo rompas!",
  str_story_banner_527200403 = "Realmente es encantador, atrayendo a tantos Eclipsitas aquí...",
  str_story_banner_527200404 = "¡Entonces, la tarea de eliminar estos residuos recae en usted!",
  str_story_banner_527200405 = "¡Él es diferente a tu Coloso! ¡Él también puede luchar!",
  str_story_banner_527200406 = "¡Este coche de carreras tiene todo tipo de artilugios y trampas diseñadas para convertir a esos cabrones en granos de arena!",
  str_story_banner_527200411 = "¡Ja ja! Muy pronto, ¡esta escoria se convertirá en polvo! Sólo pensar en ello me hace sentir mejor.",
  str_story_banner_527200412 = "¡Después de encargarse de esta inmundicia, este encantador amor va a estar bien como la lluvia! ¡Puedes colocar tantas trampas como quieras!",
  str_story_banner_527200413 = "Bullock 8 puede recuperar 1 punto de Energía cada ronda. Por supuesto, limpiar esta basura también puede acumular Energía para él.",
  str_story_banner_527200414 = "¡Por supuesto, no habrá demasiadas trampas! Después de todo, hay un límite para todo, y mi dulce amor no es uno de esos grandes y feos camiones Illumina...",
  str_story_banner_527200415 = "Tenga en cuenta que solo puede desplegar hasta 6 trampas.",
  str_story_banner_527200416 = "Aún así, puedo pedirle a mi dulce amor que quite esas trampas, ¡y no me costará nada!",
  str_story_banner_527200421 = "Esta repugnante bola de baba... Hay algo extraño en ella... ¡Parece que no le tiene miedo a esas trampas en absoluto!",
  str_story_banner_527200422 = "¡Y su repugnante habilidad puede romper trampas! ¡Mi monada Caelestite, ten cuidado!",
  str_story_banner_52740011 = "¿En serio? Soy un miembro senior ahora. ¿Por qué todavía tengo que lidiar con estas cosas?",
  str_story_banner_52740012 = "Tengo muchas ganas de volver a mi lectura. Deshagámonos de estas molestias lo antes posible.",
  str_story_banner_52740013 = "Cada vez que toca un mosaico mejorado, puede seleccionar otro punto de aterrizaje.",
  str_story_banner_52740014 = "De esa forma, puedes absorber fichas mejoradas con la Habilidad Activa y potenciar el daño final de tu Habilidad de Equipo. ¡Pongámonos en marcha!",
  str_story_banner_52740021 = "¡Haré esta misión de entrega lo mejor que pueda!",
  str_story_banner_52740022 = "Shh... ¿ves esos eclipses que nos rodean? Deshagámonos de ellos antes de salir a la carretera, solo para estar seguros.",
  str_story_banner_52740023 = "¡No hay problema!",
  str_story_banner_52740024 = "¡Acércate a ellos con la habilidad de teletransportarte y yo me encargaré del ataque!",
  str_story_banner_52840011 = "PlayerName, Siento mucho tener que pedirte que me ayudes a lidiar con esto.",
  str_story_banner_52840012 = "Es porque... solo dormí... 12 horas...",
  str_story_banner_52840013 = "Zzzzzzz...",
  str_story_banner_52840014 = "No te preocupes, Tina puede luchar incluso cuando está dormida.",
  str_story_banner_52840015 = "El método de selección de la Habilidad Activa de Tina es diferente al de otros Aurorianos. Primero, debe determinar su ruta de movimiento conectando mosaicos.",
  str_story_banner_52840016 = "Después de determinar su camino, Tina caminará dormida a lo largo de la ruta seleccionada, cambiando el color de los mosaicos a lo largo de su camino, y finalmente regresará a su punto de partida.",
  str_story_banner_52840017 = "Al conectar mosaicos, también puedes conectar el mosaico enemigo como el punto final de Tina sin consumir la cantidad de mosaicos que puedes conectar.",
  str_story_banner_52840018 = "En esta situación, Tina se detendrá en el mosaico antes del punto final y causará daño al enemigo.",
  str_story_banner_52840019 = "¡Eclipsitos! ¡Cómo os atrevéis a mostrar vuestras malas caras en Lumopolis! ¡Esto es completamente imperdonable!",
  str_story_banner_52840020 = "¡Primero aumenta la velocidad del arma al máximo y luego lanza una habilidad!",
  str_story_banner_52840021 = "¿Refuerzos? Parece que tendremos que usar algunas habilidades reales aquí.",
  str_story_banner_52840022 = "¡Usa la Habilidad Activa! ¡Libera todo el celo y acaba con ellos!",
  str_story_banner_52840023 = "¡Cómo se atreven estos asquerosos Eclipsites a profanar Lumopolis! ¡Debemos purificarlos!",
  str_story_banner_52840024 = "Plebeyo, dejaré esos débiles Eclipsites en tus manos.",
  str_story_banner_52840025 = "Limpiaré el resto.",
  str_story_banner_52840026 = "He reunido suficiente fuerza. Ahora, es mi turno de pelear.",
  str_story_banner_5299001 = "¡E-Es ese auto averiado otra vez! ¿Recuerdas cómo lo desarmamos juntos la última vez?",
  str_story_banner_5299002 = "Primero, supera eso Chainsaw Rick b-bloqueando el camino!",
  str_story_banner_5299003 = "<color=#FFB400>Tocar a un enemigo auroriano muestra su próxima acción.</color>",
  str_story_banner_5299004 = "<color=#FFB400>Los aurorianos suelen apuntar a la unidad enemiga más cercana.</color>",
  str_story_banner_5299005 = "Pero ellos <color=#FFB400>¡Solo puede moverse en mosaicos de su propio elemento!</color>\nMantenga su d-distancia y haga todo lo posible para no dejar que nos lastimen.",
  str_story_banner_5299006 = "E-Esto aquí muestra el ATK y HP del enemigo,\ny diré que es una manera bastante fácil de evaluar si estás preparado para el desafío.",
  str_story_banner_5299007 = "¡Pasemos a la acción!",
  str_story_banner_5299008 = "¡Increíble!",
  str_story_banner_5299009 = "Muy bien, Darkwasp y yo estamos ahora esperando tus órdenes.\n(S-Si tan solo pudiera dejar que Darkwasp cargara hacia adelante y encontrar un lugar para esconderse...)",
  str_story_banner_5299010 = "¡Oh, sí! ¡Lord Augean ha perfeccionado una nueva habilidad! <color=#FFB400>Al recibir daño cuerpo a cuerpo, ahora puede contraatacar al atacante.</color>!\n¡Asegúrate de aprovechar al máximo esta habilidad especial!",
  str_story_banner_5299011 = "¡Oh, no!\n¡Acabo de enterarme de que nuestro amigo que acecha en Lumopolis ha sido descubierto y está luchando contra los guardias!\n¡N-Tenemos que darnos prisa y ayudarlos!",
  str_story_banner_5299012 = "Están bastante lejos, así que intenta usar el <color=#FFB400>agujero de gusano</color> adelante para llegar más rápido.",
  str_story_banner_5299013 = "Pero todavía hay montones de aurorianos bloqueando el camino...\nSi desea evitarlos o no, depende de usted.",
  str_story_banner_5299014 = "Barbara!\nEscuché que ella puede <color=#FFB400>atacarnos y aturdirnos</color>... ¡Ella es t-aterradora!",
  str_story_banner_5299015 = "P-Pero tenemos un fuerte aliado para ayudarnos: ¡Thumper!\nThumper puede <color=#FFB400>derriba a los objetivos 2 fichas</color>!",
  str_story_banner_5299016 = "Esto no solo funciona contra los aurorianos, ¡también puedes usarlo en tus aliados de Eclipsite!\nA veces, incluso puede brindarle algunas sorpresas estratégicas...",
  str_story_banner_5299017 = "¡Darle una oportunidad!",
  str_story_banner_5299018 = "Esta parece una situación similar a la anterior, pero sin el daño de la trampa.",
  str_story_banner_5299019 = "Y-Deberías empezar a pensar en cómo vas a lidiar con Barbara...",
  str_story_banner_5299020 = "<color=#FFB400>¿Tal vez Thumper pueda impulsarnos hacia adelante?</color>",
  str_story_banner_5299021 = "¡Por fin hemos llegado a LL-Lumopolis!\n¡Vamos a derrotar a estos Lumo Guards junto con nuestros aliados de Eclipsite!",
  str_story_banner_5299022 = "<color=#FFB400>El Asistente Afónico puede restaurar HP a nuestros aliados Eclipsite dentro del alcance</color>, proporcionando apoyo vital!",
  str_story_banner_5299023 = "¡E-Es él! El hombre que se esconde en lo más profundo de Lumopolis\n—<color=#FFB400>Schwartz!</color>",
  str_story_banner_5299024 = "Estoy asustado, p-pero no podemos retroceder...",
  str_story_banner_5299025 = "¡P-Por favor j-solo ríndete! ... ¿Sueno como si hablara en serio?",
  str_story_banner_5299026 = "De todos modos, dejemos esto a Lord Augean. Como para mí...\n¡Estaré animando a todos desde atrás! Tú... ¡Tú puedes hacerlo!",
  str_story_banner_52940011 = "Diablos... Me lastimé.",
  str_story_banner_52940012 = "¿Algunos de ellos todavía están detrás de mí? No, estos tipos estaban esperando aquí para tenderme una emboscada.",
  str_story_banner_52940013 = "Parece que pusieron mucho esfuerzo en establecer esos obstáculos.",
  str_story_banner_52940014 = "Pero son demasiado ingenuos si creen que eso me detendrá.",
  str_story_banner_52940021 = "Cuidado, hay eclipses más adelante.",
  str_story_banner_52940022 = "El azulejo diagonal en el frente es un mejor lugar para atacar. Sería genial si pudiera mudarme allí.",
  str_story_banner_52940023 = "No te preocupes, puedo usar mi variante de habilidad activa para llevarnos allí.",
  str_story_banner_52940024 = "Las variantes de habilidades activas son variaciones de habilidades activas que tienen efectos ligeramente diferentes. Lanzarlo afectará el tiempo de reutilización de la siguiente habilidad activa.",
  str_story_banner_52940025 = "¡Que mis torrentes limpien todo mal!",
  str_story_banner_11900701 = "Puede llevar a cabo el refinamiento del equipo aquí. ¡Echemos un vistazo a algunas de las cosas que puedes hacer!",
  str_story_banner_11900801 = "Puede llevar a cabo el refinamiento del equipo aquí. ¡Echemos un vistazo a algunas de las cosas que puedes hacer!",
  str_story_banner_29052011 = "¿Puedes sentir que la muerte viene por ti?\nSiente lo que es la muerte para ti.",
  str_story_banner_29052012 = "Esto no es nada...!",
  str_story_banner_29052013 = "¡Aquí es donde morirás!",
  str_story_banner_29052014 = "Su resistencia es inútil.",
  str_story_banner_29052015 = "¡No no! ¡Esto es imposible!",
  str_story_banner_53040011 = "¿Entré demasiado profundo? Parece que estoy rodeado de eclipses.",
  str_story_banner_53040012 = "No se asuste, tenemos que pensar con calma en una forma de volver a salir.",
  str_story_banner_53040013 = "Usa la habilidad activa para romper el cerco de arriba primero.",
  str_story_banner_53040014 = "Débil.",
  str_story_banner_53040015 = "Hay muchas fichas mejoradas a lo largo del camino de la derecha. Recogerlos mejorará los efectos de mis habilidades. Tomemos esta ruta y eliminemos los eclipses restantes.",
  str_story_banner_53040016 = "Derrotaré a los enemigos en mi camino con mi espada. Saca tu espada!",
  str_story_banner_53040021 = "Es raro tener la oportunidad de luchar codo a codo con Colonel Yingel.",
  str_story_banner_53040022 = "Hay muchos enemigos, por favor diseñe una estrategia para nosotros, Coronel. Yingel.",
  str_story_banner_53040023 = "Seguro. Guiaré a todos hacia adelante.",
  str_story_banner_53040024 = "Deberíamos poder atacar los Eclipsites en la distancia ahora. Terminemos esto rápido.",
  str_story_banner_53040031 = "Según lo que hemos aprendido hasta ahora, hay numerosos eclipses dispersos por toda el área. Simplemente salir corriendo y atacarlos no ayudará.",
  str_story_banner_53040032 = "Esto es lo que pienso: si optamos por el enfoque Oda a las profundidades, nuestra probabilidad de ganar será del 99 %.",
  str_story_banner_53040033 = "Podemos usar Darkness Cometh ya que se han reunido en un solo lugar.",
  str_story_banner_53040034 = "Según la información que tenemos, acercarnos rápidamente a los enemigos puede darnos un 90% de posibilidades de ganar.",
  str_story_banner_53040035 = "Usaré Oda a las profundidades para cerrar la distancia.",
  str_story_banner_53130031 = "Tengo la sensación de que puedo descubrir algunos asombrosos secretos de adivinación aquí. ¡Estoy super excitado!",
  str_story_banner_53130032 = "¿Esperar lo? ¿Cómo es que ahora hay tantos eclipses? ¡No estaban allí en la adivinación de ayer!",
  str_story_banner_53130033 = "¡No importa! ¡El Libro de la Adivinación tendrá una solución!",
  str_story_banner_53130034 = "¿Esta en llamas? ¡Bueno, al menos podemos ver el rastro de luz!",
  str_story_banner_53130021 = "Los Eclipsites están llegando... Debo proteger este lugar. Esta es mi responsabilidad.",
  str_story_banner_53130022 = "El que emite un aura abrumadoramente malvada debe ser el líder de Eclipsite. Los ataques normales no tendrán mucho efecto en él.",
  str_story_banner_53130023 = "Pero mi espada no es un arma normal. Corta la cabeza de la serpiente y el resto del cuerpo seguirá.",
  str_story_banner_53130024 = "Varias hojas de Dawn se han dispersado. Esta es la oportunidad que hemos estado esperando.",
  str_story_banner_53130025 = " Usa Darkness Shattered para recuperarlos; potenciará mi ataque normal y reducirá el tiempo de reutilización de Days Without End.",
  str_story_banner_53130011 = "Urgh... Estoy herido, y todavía hay tantos eclipses.",
  str_story_banner_53130012 = "¡No te preocupes! De hecho, me siento mucho más fuerte ahora.",
  str_story_banner_53130013 = "¿Los eclipses nos están rodeando? ¡Está bien, solo usa mi Invocación para eliminarlos!",
  str_story_banner_53130014 = "Este es el poder de The Summoning... Su escudo puede evitar que esos Eclipsites incluso me toquen.",
  str_story_banner_53130015 = "Mira, el escudo ha hecho efecto. Es hora de que lancemos un contraataque.",
  str_story_banner_53130016 = "No olvides usar El nacimiento de Baba Yaga. El escudo que proporciona nos hará invencibles.",
  str_story_banner_53191011 = "¡Bienvenidos al Entrenamiento de Luminática de hoy! ¡No te preocupes, no es tan difícil como parece!",
  str_story_banner_53191012 = "Este es un curso de entrenamiento especial diseñado específicamente para mejorar tu habilidad para guiar senderos de luz, por lo que no verás ningún enemigo apareciendo aquí, ¡puedes estar seguro!",
  str_story_banner_53191013 = "Toque los mosaicos en el campo para seleccionar mosaicos del mismo elemento conectado a ellos.",
  str_story_banner_53191021 = "Después de seleccionar un mosaico, toque el área seleccionada nuevamente para eliminarlo.",
  str_story_banner_53191031 = "Cuando el número de fichas eliminadas alcance la puntuación más alta, ¡habrás superado este desafío!",
  str_story_banner_53191032 = "¡Ahora todo depende de ti, navegante! ¡Pruébelo usted mismo!",
  str_story_banner_53192011 = "Mira, hay muchas fichas azules en el campo, pero están desconectadas en el medio.",
  str_story_banner_53192021 = "Entonces, ¿así es como fluye la luz? ¡Esperar! ¡Tengo una idea!",
  str_story_banner_53192031 = "¡Mirar! ¡Tenemos tantos mosaicos azules conectados ahora! ¡Retíralos juntos!",
  str_story_banner_53192041 = "Después de eliminarlos, su puntaje alcanzó las condiciones de calificación y ahora tiene la oportunidad de usar Raging Caltrops.",
  str_story_banner_53192051 = "¡Raging Caltrops puede convertir dos fichas cromáticas! ¡Pruébelo usted mismo!",
  str_story_banner_53193011 = "Han llegado dos nuevos miembros del equipo y pueden convertir aún más fichas azules.",
  str_story_banner_53193012 = "¡Navegante, es hora de que tomes las riendas!",
  str_story_banner_53194011 = "Tenemos nuevos contenidos de entrenamiento para ti... ¡Mira! ¡Ha aparecido una loseta de Runa en el campo!",
  str_story_banner_53194021 = "Si no te encargas de él rápidamente, se convertirá en un mosaico roto, ¡lo que significa un gran problema!",
  str_story_banner_53195011 = "Muchos Aurorianos del Bosque son expertos en utilizar fichas mejoradas.",
  str_story_banner_53196011 = "Ahora es el momento de que los Fire Aurorians se pavoneen y se enfrenten a un escenario completamente nuevo.",
  str_story_banner_53197011 = "La prueba final... Esto no será fácil.",
  str_story_banner_53197012 = "¡Tu objetivo esta vez es eliminar tantas fichas como sea posible dentro del límite de la ronda y superar la puntuación más alta!",
  str_story_banner_53197013 = "Cada vez que logre un objetivo de calificación en una etapa de desafío, la etapa se actualizará.",
  str_story_banner_53197021 = "A medida que se actualiza una etapa, ¡su dificultad también aumentará!",
  str_story_banner_53197022 = "¡Navegador, es hora de liberar tu verdadero poder!",
  str_story_banner_60121011 = "A medida que te acercas al borde del desierto, una niebla flota en el aire, ocultando quizás a las criaturas exiliadas dentro. A pesar de nuestro conocimiento limitado de este lugar, no hay necesidad de entrar en pánico. Parece que alguien se ha aventurado aquí antes que nosotros...",
  str_story_banner_60121012 = "Se han agregado al Códice Desolación la clasificación, la recompensa de caza y el puerto exiliado.",
  str_story_banner_60121013 = "¡Veámoslos!",
  str_story_banner_60121031 = "Fiel a su nombre, el legendario desierto de Desolation Codex contiene información limitada. Sin embargo, a medida que explore más sus secretos, desbloqueará recompensas más increíbles.",
  str_story_banner_60121032 = "Cuando finalice el ciclo actual de Desolation Codex, recibirás Expresiones olvidadas y Susurros olvidados según tu clasificación.",
  str_story_banner_60121033 = "Puedes intercambiar Expresiones olvidadas y Susurros olvidados por Solamber, Aurorians y Star Flares en Exiled Harborage.",
  str_story_banner_60121051 = "En la clasificación actual, los navegantes se ordenan según el daño que infligen al jefe. Los navegantes de alto rango reciben mejores emblemas como recompensa.",
  str_story_banner_60121091 = "¡Desafía al Jefe de este ciclo Ahora!",
  str_story_banner_60122011 = "A medida que te acercas al borde del desierto, una niebla flota en el aire, ocultando quizás a las criaturas exiliadas dentro. A pesar de nuestro conocimiento limitado de este lugar, no hay necesidad de entrar en pánico. Parece que alguien se ha aventurado aquí antes que nosotros...",
  str_story_banner_60122012 = "Nuestra tarea en Desolation Codex es enfrentarnos a un Boss conocido como The Forsaken o algo así. Las recompensas que recibamos, como rangos, emblemas y Lumamber, estarán determinadas por el daño que inflijamos al Jefe.",
  str_story_banner_60122051 = "Puede ver los estándares de daño y las recompensas de todos los rangos aquí.",
  str_story_banner_60122052 = "Al final de cada ciclo, se entregarán recompensas y emblemas según tu rango. Cuanto más alto sea tu rango, mayores serán las recompensas.",
  str_story_banner_60122053 = "Su emblema se mostrará en su avatar personal como símbolo de sus logros.",
  str_story_banner_60122054 = "Cuando finalice el ciclo actual de Desolation Codex, recibirás Expresiones olvidadas y Susurros olvidados según tu clasificación.",
  str_story_banner_60122055 = "Puedes intercambiar Expresiones olvidadas y Susurros olvidados por Solamber, Aurorians y Star Flares en Exiled Harborage.",
  str_story_banner_60122071 = "En la clasificación actual, los navegadores se ordenan según el daño que infligen al jefe. Los Navegantes de alto rango reciben mejores emblemas como recompensa.",
  str_story_banner_60122111 = "¡Desafía al Jefe de este ciclo Ahora!",
  str_story_banner_53240021 = "¡Mira, han aparecido eclipses en la distancia! ¡Pero no te preocupes! ¡Tengo su espalda!",
  str_story_banner_53240022 = "Extraño. ¿Cómo es que no son eliminados...",
  str_story_banner_53240023 = "¡Ah, entonces los Eclipsites bloquearon el camino con mosaicos rotos, impidiendo que nos acercáramos para atacar!",
  str_story_banner_53240024 = "Parte de mi trabajo es eliminar todos los obstáculos y despejarte el camino.",
  str_story_banner_53240025 = "Lanza habilidad activa para conectar más mosaicos. Luego usaré el Chain Combo para eliminar estos obstáculos.",
  str_story_banner_53240011 = "Parece que hoy va a ser un día tranquilo, PlayerName.",
  str_story_banner_53240012 = "¿Oh? ¿Eclipsitos? Una oportunidad perfecta para estirar esos músculos.",
  str_story_banner_53240013 = "Este eclipse es débil. Primero ocupémonos del de la izquierda.",
  str_story_banner_53240014 = "PlayerName, ha entrado en el estado de Sabiduría Sagrada y ganado puntos de Sabiduría. Puedes ver el marcador encima de su barra de HP.",
  str_story_banner_53240015 = "Cuando inflijo daño a enemigos en el estado de Sabiduría Sagrada, puedo ignorar sus escudos y convertir el daño en puntos de Sabiduría.",
  str_story_banner_53240016 = "Cuando los puntos de Sabiduría exceden el HP actual del enemigo, puedo matarlo independientemente de su escudo. ¡Terminemos esto rápido!",
  str_story_banner_53340021 = "PlayerName, el primer paso para un hombre maduro siempre es mantener la compostura.",
  str_story_banner_53340022 = "Es un poco molesto ahora, pero lo solucionaré en poco tiempo.",
  str_story_banner_53340023 = "Recolectaré azulejos azules con mi poder para activar Desde Dawn Hasta el Anochecer para sanar.",
  str_story_banner_53340024 = "A continuación, Paso 2: Aprende a lidiar con los golpes",
  str_story_banner_53340025 = "Mi Habilidad Activa, Danza de Sueños Despiertos, puede mezclar las filas y columnas con solo unos toques. Ahora, te toca a ti.",
  str_story_banner_53340011 = "¿Eclipsites en mi territorio? ¡Eso amenaza mi inversión! Solo observa, ¡les mostraré la puerta yo mismo!",
  str_story_banner_53340012 = "Usa el Jackpot para enviarlos lejos!",
  str_story_banner_53340013 = "Nos hemos desviado un poco. Necesitamos cubrir un poco más de terreno para volver al camino correcto.",
  str_story_banner_53340014 = "¡Ve a lo grande o vete a casa! Y la mejor parte es: el riesgo es todo tuyo.",
  str_story_banner_53340015 = "Eve¡Todos listos! ¡Vamos a acabar con ellos de un solo golpe!",
  str_story_banner_80010101 = "Navegador, parece Eve está atrapado en un sueño!",
  str_story_banner_80010201 = "¿Qué pasa conmigo? Mi cabeza da vueltas...",
  str_story_banner_80010301 = "¿Adónde se fue la sombra...?",
  str_story_banner_80010401 = "¿Qué dejó caer la sombra?",
  str_story_banner_53340031 = "Los enemigos están dispersos, por lo que debemos desplegar un Iron Lizard en el centro para detenerlos y eliminarlos.",
  str_story_banner_53340032 = "¡Toca el lagarto de hierro y en cada ronda puedes usar Magnetix o Whirlpool para adaptarte a la situación del campo de batalla!",
  str_story_banner_53440021 = "Los Eclipsites vienen. ¡Es mi responsabilidad proteger este lugar!",
  str_story_banner_53440022 = "¡Desata el Bombardeo Sagrado sobre el enemigo con la mayor cantidad de pilas de Voluntad Persistente!",
  str_story_banner_53440023 = "¡Criaturas de la oscuridad perpetua! ¡Siente el poder del Dios de la Luz!",
  str_story_banner_53430011 = "Vamos a calentarnos, PlayerName, ¡empezando por el más grande!",
  str_story_banner_53430012 = "Con el nuevo Barón Rojo, su poder puede amplificarse bajo condiciones específicas. Asegúrate de tener esto en cuenta para las próximas batallas.",
  str_story_banner_53430013 = "Los enemigos atacados por Habilidades Activas quedan en estado de Eco Atronador. Cada vez que hago un movimiento, infligo daño a los enemigos cercanos bajo el estado de Eco Atronador.",
  str_story_banner_53430014 = "Ahora, por favor guíame, PlayerName. Te mostraré mi fuerza.",
  str_story_banner_50620001 = "¿En serio, PlayerName? ¿Asustado de estos Eclipsites?",
  str_story_banner_50620002 = "No te preocupes. La justicia puede ser tardía, pero mis viñas y yo nunca lo somos.",
  str_story_banner_50620003 = "Terminemos con esto; es otro día aburrido.",
  str_story_banner_50620011 = "PlayerName, estoy encantado de que estés conmigo en esta patrulla por el bosque.",
  str_story_banner_50620012 = "Parece que no solo los Eclipsites acechan aquí, sino que también la tierra está contaminada.",
  str_story_banner_50620013 = "No te preocupes; con tu ayuda, resolveremos esto.",
  str_story_banner_50620014 = "Esta es la fuerza de la purificación. Es hora de derribar a estos Eclipsites.",
  str_story_banner_80020101 = "¿Pam? ¿Por qué estás de vuelta otra vez?",
  str_story_banner_80020102 = "¿E-Eres tú... Dama Irridon? Apenas te reconocí con esa vestimenta.",
  str_story_banner_80020103 = "¡Debo ir y apelar! ¡No puedo permitir que mi familia sufra esta injusticia!",
  str_story_banner_80020104 = "¡Ahora no es el momento!",
  str_story_banner_80020105 = "¿Incluso tú me estás deteniendo?",
  str_story_banner_80020106 = "¡Ahora, vete de inmediato, a menos que puedas derrotarme!",
  str_story_banner_80020201 = "¿Es esa... Mirren Gautier?!",
  str_story_banner_80020202 = "Él es la raíz de todos nuestros problemas, trayendo deshonra a nuestra familia.",
  str_story_banner_80020203 = "Oh, Dios de la Luz, si puedes ver esto, ¿por qué dejarlo vagar libremente? ¿No piensas protegernos?",
  str_story_banner_80020204 = "¡Ahora no tengo más opción que tomar el asunto en mis propias manos!",
  str_story_banner_80020301 = "Mejor aún... ¿Quién eres tú, de todos modos?",
  str_story_banner_80020302 = "Juez Principal, mi familia y yo hemos sido acusados injustamente, ¡y esperamos que pueda ayudarnos a buscar justicia y limpiar nuestros nombres!",
  str_story_banner_80020303 = "Entonces, ¿te declaran culpable?",
  str_story_banner_80020304 = "Cada juicio dictado por el Salón de Justicia está sancionado por el Dios de Luz, sin absolutamente ningún margen de error.",
  str_story_banner_80020305 = "Siendo culpable, te negaste a admitir tu falta y enfrentar el castigo e irrumpiste ilegalmente en el Salón de la Justicia, profanando nuestros sagrados juicios...",
  str_story_banner_80020306 = "¡Eres simplemente atroz y mereces ser castigado aún más!",
  str_story_banner_80020307 = "...",
  str_story_banner_53540021 = "PlayerName, todavía nos queda algo de distancia, pero ya casi llegamos.",
  str_story_banner_53540022 = "Si perdemos esta oportunidad de observación, quién sabe cuánto tiempo tendremos que esperar para la próxima.",
  str_story_banner_53540023 = "¡Nunca pensé que nos encontraríamos con Eclipsites aquí! ¡Quédate cerca de mí!",
  str_story_banner_53540024 = "Obtendremos sanación adicional si nos posicionamos en el área elegida. Creo que puedes aprovecharlo.",
  str_story_banner_53540011 = "Entonces, así es como se ve el mundo exterior...",
  str_story_banner_53540012 = "Incluso sin mi hermana a mi lado, ¡encontraré el valor para luchar!",
  str_story_banner_53540013 = "Puedo convertir libremente las casillas seleccionadas Amarillas o Verdes en casillas Azules.",
  str_story_banner_53540014 = "¡Comencemos lanzando la Granizada Invernal y dando un toque helado a la tierra!",
  str_story_banner_53540015 = "No puedes aprovechar el poder del viento y la nieve uno tras otro. ¡Intenta lanzar la Ventisca Eterna en la siguiente ronda!",
  str_story_banner_53540031 = "Buscando señales... Enemigo avistado. Desplegando el Reino y listo para recolectar datos!",
  str_story_banner_53540032 = "Durante la cuenta regresiva, los Navegantes pueden intercambiar los elementos de las casillas adyacentes para planificar una ruta de ataque más adecuada.",
  str_story_banner_700102 = "La lista de deseos está disponible en este reclutamiento por tiempo limitado y contiene 1 auroriano fijo y 4 aurorianos de tu elección.",
  str_story_banner_700103 = "Selecciona un Auroriano de 6 estrellas de cada uno de los cuatro elementos para los 4 Aurorianos opcionales restantes.",
  str_story_banner_700104 = "La lista de deseos entra en vigor después de que se determinen los 4 Aurorianos.",
  str_story_banner_700105 = "Cuando la lista de deseos entre en vigor, se garantiza que todos los Aurorianos de 6 estrellas reclutados estarán incluidos en la lista de deseos.",
  str_story_banner_501400511 = "No puedo creer que haya tantos Eclipsites en la Bahía de los Pabellones Gemelos. Ten cuidado al enfrentarte a ellos para evitar dañar a los residentes cercanos.",
  str_story_banner_501400512 = "¡Presta mucha atención a las posiciones de los enemigos! Parece que hay un camino de casillas rojas que se puede utilizar; ¡Usa las Begonias Brillantes para conectarlo!",
  str_story_banner_501400513 = "¡Toma esto!",
  str_story_banner_501400514 = "Con el camino conectado, los grandes Eclipsites en frente han sido <color=#FFB400>eliminados</color> por las Shining Begonias. ¡Ahora, dirígete a la parte noreste del campo de batalla para lidiar con los Eclipsites restantes!",
  str_story_banner_501400515 = "¿Eh? El reloj de arena en el suelo parece haberse creado justo después de que se rompió la piedrecita, ofreciendo una gran oportunidad para reducir el tiempo de enfriamiento de las Begonias Brillantes. ¡Probemos con las fichas verdes esta vez!",
  str_story_banner_501400611 = "¡Hay bastantes Eclipsites! Pero debemos hacerlo rápido. ¡Todos, manténganse a salvo!",
  str_story_banner_501400612 = "Los caminos que rodean a este Eclipsite son todos rojos. Comencemos usando Begonias Brillantes para conectar el camino y luego <color=#FFB400>lanzar Ataques Normales a este Eclipsite desde diferentes direcciones</color>, maximizando el efecto de En Tiempos de Necesidad!",
  str_story_banner_501400613 = "¡Excelente! Aprovechemos este impulso y eliminemos a todos los Eclipsites.",
  str_story_banner_81001011 = "¿Recuerdas, PlayerName? ¡Un extraño cubo apareció en el Obelisco del Retorno!",
  str_story_banner_81001012 = "Parece que ese cubo puede activar un dispositivo de entrenamiento Luminatics diseñado por los Caelestitas...",
  str_story_banner_81002011 = "Alerta: El entrenamiento ha comenzado oficialmente. Continuarás enfrentándote a múltiples etapas en cada sesión de entrenamiento.",
  str_story_banner_81003011 = "Si te quedas sin rondas o eres derrotado, la sesión de entrenamiento actual se terminará y no podrás continuar con tu desafío.",
  str_story_banner_81003012 = "Después de completar exitosamente todas las etapas, la ronda actual de entrenamiento finalizará. Buena suerte, Papá.",
  str_story_banner_81004011 = "Módulo de entrenamiento activado...",
  str_story_banner_81004012 = "Durante el programa de entrenamiento, simplemente debes tocar y eliminar las fichas para luchar contra los Eclipsites.",
  str_story_banner_81004013 = "Toca las casillas para seleccionar casillas del mismo elemento conectadas a ellas. Al hacerlo, verás una vista previa del Combo en Cadena del Aurorian.",
  str_story_banner_81004014 = "Pruébalo tú mismo.",
  str_story_banner_81005011 = "Al tocar nuevamente las casillas seleccionadas, se eliminarán y los Aurorianos del mismo elemento que las casillas lanzarán sus Combos en Cadena.",
  str_story_banner_81006011 = "Continúa la batalla y derrota a todos los enemigos para completar el entrenamiento.",
  str_story_banner_53740021 = "¿Realmente podré cobrar alguna deuda aquí?",
  str_story_banner_53740022 = "Vaya, en lugar de encontrar holgazanes, me encontré con algunos Eclipsites.",
  str_story_banner_53740023 = "Será mejor que termine con todos rápidamente. Ya estoy empezando a extrañar a Rebecca ahora.",
  str_story_banner_53740011 = "Eclipsitos... ¿Por qué están aquí?",
  str_story_banner_53740012 = "Intentaré acercarme a ellos y hacer que se \"vayan\" sin dolor...",
  str_story_banner_53740013 = "Lanza la Habilidad Activa Danza de Mariposas para convertir las casillas azules alrededor de los monstruos en casillas oscuras.",
  str_story_banner_53740014 = "Después de pasar por un mosaico oscuro, el elemento del mosaico que se actualice allí debe ser el mismo que antes.",
  str_story_banner_53740015 = "Deja de resistirte. Terminará en un instante y no dolerá... mucho.",
  str_story_banner_551103 = "Echa un vistazo, Navegante. Ha surgido una nueva área. ¡Vamos a ver!",
  str_story_banner_53840011 = "En las enigmáticas profundidades del mar, abundan los barcos hundidos, escondiendo innumerables maravillas de Longzhou bajo las olas. Afortunadamente, con la ayuda de la experiencia mecánica, podemos intentar rescatar los restos del barco, trayendo estos tesoros enterrados de vuelta a la luz del día.",
  str_story_banner_53840021 = "Por favor, ten en cuenta que cuando el área de salvamento esté llena, ¡el salvamento terminará en fracaso!",
  str_story_banner_53840031 = "¡Logra la victoria al rescatar con éxito todas las reliquias en el campo!",
  str_story_banner_53840032 = "¡Navegante, ahora está en tus manos!",
  str_story_banner_53840041 = "¡Prepárate para el desafío definitivo!",
  str_story_banner_53840042 = "Aquí, abundan las reliquias y debes esforzarte por rescatar tantas reliquias como sea posible dentro del tiempo limitado.",
  str_story_banner_53840043 = "Al concluir, las recompensas se distribuirán según la puntuación que hayas obtenido.",
  str_story_banner_53840044 = "¡Navegador, es hora de mostrar tus verdaderas capacidades!",
  str_story_banner_53840111 = "¿Por qué de repente hay tantos Eclipsites aquí? El de la izquierda parece especialmente duro. Tendremos que establecer un Arreglo Cuadrado de Truenos y luchar contra él con cuidado.",
  str_story_banner_53840112 = "Usa el Tirón de Parasol para eliminar a todos los demás enemigos que están dispersos por todas partes.",
  str_story_banner_53840113 = "Es extremadamente ventajoso para nosotros luchar contra enemigos en la Formación Cuadrada de Trueno. ¡Úsala bien para ganar todas tus batallas!",
  str_story_banner_53940311 = "Vaya, estoy rodeado de Eclipsites. Solo porque soy pequeño no significa que sea fácil de molestar.",
  str_story_banner_53940312 = "Escuché que algunos Eclipsites roban antigüedades... ¿Realmente saben lo que están robando...?",
  str_story_banner_53940313 = "Utiliza Exposición Completa y acércate a ellos para examinarlos cuidadosamente.",
  str_story_banner_53940211 = "Oh, eres tú, señor Istvan. Tu ropa...",
  str_story_banner_53940212 = "Olvida eso por ahora, pequeña niña. Resolvamos primero el problema que tenemos entre manos.",
  str_story_banner_53940213 = "El juego de ajedrez ha comenzado.",
  str_story_banner_53940214 = "Pequeña niña, muéstrame tu habilidad para controlar la Espada Mágica.",
  str_story_banner_53940215 = "Gracias por ayudarme, Señor de las Sombras.",
  str_story_banner_53940216 = "El juego está decidido. Es hora de poner fin a esta farsa.",
  str_story_banner_53940217 = "Mis sombras llenarán los huecos y lo completarán.",
  str_story_banner_53940111 = "Selecciona Estrategias de Inversión durante la batalla para mejorar las habilidades de Sheol en todos los aspectos.",
  str_story_banner_53940112 = "El Capital obtenido en las batallas se mostrará en un área designada. Toca esto para ir a Estrategia de Inversión.",
  str_story_banner_53940113 = "Las seis habilidades aquí se dividen en tres grupos y se desbloquearán a medida que Sheol acumule más Capital. Cada vez que se desbloquee un grupo, selecciona una de las dos habilidades y toca Invertir para obtener esta habilidad. La selección no se puede cambiar en esta batalla.",
  str_story_banner_53940114 = "Después de completar la primera ronda de inversión, Sheol puede hacer una segunda ronda de inversión para obtener una habilidad de combate que no tenía en la primera ronda de inversión.",
  str_story_banner_53940115 = "Actualmente tienes 5 Capitales. Intenta hacer una inversión en Shadow Snake Entanglement y Rich and Powerful ahora para ver qué sucede.",
  str_story_banner_53940116 = "¡La Habilidad Activa y el Combo en Cadena han sido mejorados! También se pueden hacer inversiones en batallas posteriores para obtener habilidades bloqueadas.",
  str_story_banner_8024001 = "Parece que los enemigos están fuera de alcance.",
  str_story_banner_8024002 = "Bueno, ya que ese es el caso, permíteme intentar un enfoque diferente para combatir.",
  str_story_banner_8024003 = "A continuación, déjame intentarlo.",
  str_story_banner_8024004 = "Han aparecido nuevos enemigos. Déjame encargarme de ellos.",
  str_story_banner_8024005 = "Ahora puedo sentir el poder del Nodo de Formación. Intentemos eliminar a todos los enemigos.",
  str_story_banner_5414011 = "Hola PlayerName, he encontrado un montón de cosas geniales en este mundo desde que desperté. ¿Te importaría acompañarme a verlas hoy?",
  str_story_banner_5414012 = "Pero como la Doncella del Dragón, primero debo ocuparme de los problemas cercanos.",
  str_story_banner_5414013 = "No tengo muchas oportunidades para mostrar mis habilidades, así que más te vale apreciarlas.",
  str_story_banner_5414014 = "¡Bien, mírame mientras manejo este desastre!",
  str_story_banner_5414031 = "A medida que se acerca el Festival de Primavera, los espíritus malignos están causando problemas de nuevo.",
  str_story_banner_5414032 = "Los enemigos están agrupados en la esquina y los métodos convencionales no parecen poder eliminarlos a todos de una vez. Este es el momento perfecto para usar mi habilidad activa: ¡Granada Sorpresa! Vamos, Ah Ding, marquemos las posiciones de los enemigos y eliminémoslos con daño de área.",
  str_story_banner_5414033 = "Oh, olvidé decirte, mi Granada Sorpresa tiene varias variantes. Puedes elegir lanzar una de varias habilidades variantes, cada una con un período de enfriamiento diferente después de lanzar.",
  str_story_banner_5414034 = "La Variante I de Granada Sorpresa potencia los Ataques Normales, mientras que la Variante II de Granada Sorpresa otorga el efecto de retroceso a los Combos en Cadena después de ser lanzados. ¡Selecciona sabiamente diferentes habilidades variantes según la situación para maximizar tu daño!",
  str_story_banner_54193101 = "Dicen que me he vuelto loco... ¿Tú también estás loco? ¿Justo como yo?",
  str_story_banner_54193102 = "¿Loco? Jeje... ¡Jajaja! Llámame loco si quieres.",
  str_story_banner_54193103 = "Claymore, tú... ¿Estás intentando ocultar tu verdadero yo bajo ese nombre? Aquiles, dime, ¿qué está pasando?!",
  str_story_banner_54193104 = "Debo bajarte...",
  str_story_banner_54193105 = "¡Eso es lo que está pasando aquí!",
  str_story_banner_54193106 = "Adras",
  str_story_banner_54193107 = "Aquiles",
  str_story_banner_16022511 = "¡Hmph! ¿Crees que puedes atraparme solo actuando juntos?",
  str_story_banner_16022512 = "No te preocupes. Para un cazador increíble como yo, la presa está llena de puntos débiles!",
  str_story_banner_16022513 = "Durante la caza, la presa a menudo revela muchos puntos débiles. ¡La primera regla de la caza es encontrar y explotar estos puntos débiles!",
  str_story_banner_16022514 = "¡Una vez que descubra sus puntos débiles, estas presas no tendrán ninguna oportunidad contra mi lanza!",
  str_story_banner_900107011 = "Comentario: Los recuerdos y emociones dejados por los soñadores originales se envuelven capa por capa en energía de sueño, formando Esferas de Sueño.",
  str_story_banner_900107012 = "Como tu Enlightener, tengo que recordarte que durante la exploración, tendrás la oportunidad de obtener Orbes de Sueño dispersos por todo el sueño.",
  str_story_banner_900107013 = "Al colocar las Esferas de Sueño en la Espiral de Iluminación, puedes analizar los recuerdos de combate dentro de las Esferas de Sueño, desbloqueando habilidades relacionadas para ayudar a los Aurorians en la batalla.",
  str_story_banner_900108011 = "Consejo: El Enlightener cambiará al modo Cubo de Iluminación, permitiéndole luchar junto a los Aurorians.",
  str_story_banner_900108012 = "En batalla, el Enlightener gana 1 punto de energía por cada mosaico que los Aurorianos atraviesan.",
  str_story_banner_900108013 = "Después de que los Aurorians terminen de conectar las fichas y se desaten todos sus Combos en Cadena, si el Enlightener ha acumulado más energía de la requerida por las Esferas de Sueño, puedes liberar las habilidades de las Esferas de Sueño en la Espiral de Iluminación.",
  str_story_banner_900108014 = "Ahora puedes intentar conectar mosaicos una vez.",
  str_story_banner_900108021 = "Buenas noticias: Has obtenido energía. Puedes ver el estado de carga y los detalles de ensamblaje de los Orbes de Sueño aquí.",
  str_story_banner_900108031 = "Comentario: Existen muchos tipos de Orbes de Sueño, entre los cuales los Orbes de Carga pueden ayudarte a obtener energía adicional y acelerar el progreso de carga.",
  str_story_banner_900108032 = "Mientras tanto, los Orbes de Mejora pueden fortalecer los Orbes de Habilidad en la Espiral de Iluminación.",
  str_story_banner_900108033 = "Las combinaciones inteligentes pueden liberar todo el potencial de las Esferas de Sueño. Como tu Enlightener, creo que seguramente encontrarás alegría en esto.",
  str_story_banner_5416011 = "¿Han aparecido Eclipsites más adelante? Suena como un trabajo para los cazadores de águilas.",
  str_story_banner_5416012 = "Mantén tu posición y usa la Muerte Recon para explorar una ruta de infiltración.",
  str_story_banner_5416013 = "¡Informe! Eagle Hunter Zero ha infiltrado el territorio enemigo; ¡ha llegado el momento de comenzar nuestro asalto! ¡Solicito que todos los drones ataquen al enemigo!",
  str_story_banner_5416014 = "¡Intenta usar Death Recon de nuevo! Me pondrá en estado de agotamiento y me impedirá usar ataques normales o combos en cadena... ¡Pero los Eagle Hunters se enfocarán en el enemigo y los eliminarán en mi lugar!",
  str_story_banner_5416021 = "¡Buenas noticias, el Último Caelestite! Hoy, tienes el privilegio de luchar junto al legendario Zeta, el salvador de todo Astra!",
  str_story_banner_5416022 = "Ya has conocido a mi otro miembro del grupo, ¿verdad? Estoy hablando de este robot explosivamente adorable: ¡Conan el Iluminado!",
  str_story_banner_5416023 = "¡Conan el Iluminado no obedece a nadie más que a mí! ¿Bastante genial, verdad?",
  str_story_banner_5416024 = "Harías bien en recordar esto, el último Caelestite: una vez que el Tablero de Colores esté cubierto con los cuatro colores, puedes invocar a un nuevo Conan el Iluminado. No comparto esta habilidad secreta con cualquiera, así que manténlo en secreto, ¿de acuerdo?",
  str_story_banner_5466011 = "¡Estoy a punto de establecer un nuevo récord para Tetrablox! Pero hay Eclipsites... No hay otra opción. ¡Tendré que eliminarte para conseguir más puntos!",
